<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sea Gull | Admin Pro</title><style>
:root{--bg:#06121c;--panel:#0c1d2b;--panel2:#10283a;--line:#1e3b50;--text:#f6f8fb;--muted:#91a6b7;--blue:#2d8cff;--cyan:#22c7d8;--green:#18c77a;--gold:#f4bb42;--red:#ef5366;--shadow:0 18px 55px #0006}*{box-sizing:border-box}html{background:var(--bg)}body{margin:0;background:radial-gradient(circle at 10% 0,#123a55 0,#06121c 35%,#040b12 100%);color:var(--text);font-family:Tahoma,Arial,sans-serif}button,input,select,textarea{font:inherit}.top{height:74px;position:sticky;top:0;z-index:50;background:#061522ee;backdrop-filter:blur(14px);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 22px}.brand{display:flex;align-items:center;gap:12px}.brand-logo{width:46px;height:46px;border-radius:14px;background:#fff;color:#0b3b39;display:grid;place-items:center;font-weight:900}.brand b{font-size:19px}.brand small{display:block;color:var(--muted);font-size:11px}.top-actions{display:flex;gap:8px}.btn{border:1px solid var(--line);background:#10283a;color:#fff;border-radius:10px;padding:9px 13px;cursor:pointer}.btn:hover{border-color:#4c83ad}.btn.primary{background:var(--blue);border-color:var(--blue)}.btn.green{background:#0b5a3c;border-color:#168455}.btn.red{background:#5a1e2b;border-color:#853142}.layout{display:grid;grid-template-columns:240px 1fr;direction:ltr}.side{direction:rtl;min-height:calc(100vh - 74px);position:sticky;top:74px;height:calc(100vh - 74px);overflow:auto;background:#061522dd;border-left:1px solid var(--line);padding:16px}.nav{display:grid;gap:5px}.nav button{border:0;background:transparent;color:#afbdca;padding:12px;border-radius:11px;text-align:right;cursor:pointer;display:flex;justify-content:space-between;align-items:center}.nav button:hover,.nav button.active{background:#12314a;color:#fff}.pill{background:#1c3850;border-radius:999px;padding:3px 8px;font-size:11px}.pill.red{background:#9b2b40;animation:pulseNew 1s infinite}@keyframes pulseNew{50%{transform:scale(1.08);box-shadow:0 0 0 6px #9b2b4020}}.adminbox{margin-top:25px;padding:14px;border:1px solid var(--line);border-radius:14px;background:#0b1c2a;color:#c9d6e1}.adminbox small{color:var(--muted)}main{direction:rtl;max-width:1700px;width:100%;margin:auto;padding:25px}.page{display:none}.page.active{display:block}.welcome{display:flex;justify-content:space-between;align-items:end;margin-bottom:18px}.welcome h1{margin:0;font-size:27px}.welcome p{margin:6px 0;color:var(--muted)}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.stat{position:relative;overflow:hidden;background:linear-gradient(145deg,#10283a,#0b1b29);border:1px solid var(--line);border-radius:16px;padding:18px;box-shadow:var(--shadow)}.stat .label{color:#9eb0bf;font-size:12px}.stat .value{font-size:29px;font-weight:800;margin-top:8px}.stat .sub{font-size:10px;color:var(--muted);margin-top:5px}.grid{display:grid;grid-template-columns:1fr 330px;gap:16px;margin-top:16px}.panel{background:linear-gradient(145deg,#0d2030,#091723);border:1px solid var(--line);border-radius:16px;overflow:hidden;box-shadow:var(--shadow)}.panel-head{padding:15px 17px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:10px}.panel-head h2{margin:0;font-size:16px}.filters{display:flex;gap:7px;flex-wrap:wrap}.search,.select,.field input,.field select,.field textarea{background:#071521;border:1px solid var(--line);color:#fff;border-radius:10px;padding:10px;outline:none}.search{width:260px}.table-wrap{overflow:auto}.orders{width:100%;border-collapse:collapse;min-width:1050px}.orders th{background:#091724;color:#71889a;font-size:11px;padding:11px 12px;text-align:right}.orders td{padding:12px;border-top:1px solid #173047;font-size:12px}.orders tr:hover{background:#10273a}.order-no{color:#5bb0ff;font-weight:800}.muted{color:var(--muted);font-size:10px;margin-top:3px}.money{font-weight:800}.status{display:inline-flex;padding:5px 8px;border-radius:999px;font-size:10px;font-weight:800;white-space:nowrap}.new{background:#143c73;color:#75baff}.accepted{background:#4b330c;color:#ffd05c}.preparing{background:#4d360d;color:#ffd76c}.ready{background:#083f4d;color:#5ce0ef}.out_for_delivery{background:#163d72;color:#7ebdff}.delivered{background:#083d2b;color:#62e8a9}.cancelled{background:#4a1c27;color:#ff8090}.actions{display:flex;gap:5px}.mini{border:1px solid var(--line);background:#0c1d2b;color:#fff;border-radius:8px;padding:6px 8px;cursor:pointer}.queue{padding:14px;display:grid;gap:8px}.action-queues{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding:14px}.action-queue{border:1px solid var(--line);border-radius:14px;background:#091824;overflow:hidden}.action-queue-head{padding:11px 12px;border-bottom:1px solid var(--line);font-weight:800;display:flex;justify-content:space-between;gap:8px}.action-queue-body{padding:9px;display:grid;gap:7px;max-height:280px;overflow:auto}.action-item{border:1px solid #173047;border-radius:10px;padding:9px;background:#0b1d2a;cursor:pointer}.action-item:hover{background:#102b40}.action-item b{color:#5bb0ff}.action-item small{display:block;color:var(--muted);margin-top:3px}.action-count{border-radius:999px;padding:2px 7px;background:#173047;font-size:10px}.action-count.hot{background:#8d283b;color:#fff}.queue-empty{color:var(--muted);padding:12px;text-align:center;font-size:11px}@media(max-width:1100px){.action-queues{grid-template-columns:1fr 1fr}}@media(max-width:650px){.action-queues{grid-template-columns:1fr}}.q{border:1px solid var(--line);border-radius:12px;padding:11px;background:#091824}.qtop{display:flex;justify-content:space-between;font-size:11px}.q b{color:#59b1ff}.q .price{color:#6be5aa;font-weight:800;margin-top:6px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.card{border:1px solid var(--line);background:#091824;border-radius:14px;padding:15px}.card h3{margin:0 0 8px;font-size:14px}.card .big{font-size:24px;font-weight:800}.products{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;padding:15px}.product{border:1px solid var(--line);background:#091824;border-radius:12px;padding:12px}.product .phead{display:flex;justify-content:space-between;gap:8px}.product b{font-size:12px}.product .price{color:#6be5aa;font-weight:800;margin-top:8px}.product small{display:block;color:var(--muted);margin-top:3px}.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;padding:16px}.field label{display:block;color:#9fb0be;font-size:11px;margin-bottom:5px}.field input,.field select,.field textarea{width:100%}.field textarea{min-height:90px}.modal-backdrop{position:fixed;inset:0;background:#000b;display:none;align-items:center;justify-content:center;padding:16px;z-index:100}.modal-backdrop.open{display:flex}.modal{width:min(850px,100%);max-height:92vh;overflow:auto;background:#0c1d2b;border:1px solid var(--line);border-radius:18px;box-shadow:0 30px 90px #000b}.modal-head{position:sticky;top:0;z-index:2;background:#0c1d2b;border-bottom:1px solid var(--line);padding:15px 18px;display:flex;justify-content:space-between}.modal-body{padding:18px}.detail-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.detail{background:#091824;border:1px solid var(--line);border-radius:10px;padding:10px}.detail small{display:block;color:var(--muted);font-size:10px;margin-bottom:4px}.items{width:100%;border-collapse:collapse;margin-top:15px}.items th,.items td{border-bottom:1px solid var(--line);padding:9px;font-size:11px;text-align:right}.items th{color:var(--muted)}.modal-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:16px}.toast{position:fixed;left:20px;bottom:20px;background:#12314a;border:1px solid #315a79;color:#fff;padding:12px 15px;border-radius:11px;display:none;z-index:200}.alarm{position:fixed;inset:0;pointer-events:none;display:none;z-index:90;background:#e33b4510}.alarm.on{display:block;animation:blink 1s infinite}@keyframes blink{50%{background:#e33b451f}}.report-tools{display:flex;gap:8px;align-items:end;flex-wrap:wrap;padding:15px}.report-table{width:100%;border-collapse:collapse}.report-table th,.report-table td{padding:9px;border-bottom:1px solid var(--line);font-size:11px;text-align:right}.login{min-height:100vh;display:grid;place-items:center;padding:20px}.login-card{width:min(420px,100%);background:#0c1d2b;border:1px solid var(--line);border-radius:20px;padding:28px;box-shadow:var(--shadow);text-align:center}.login-card input{width:100%;margin:12px 0;background:#071521;color:#fff;border:1px solid var(--line);border-radius:10px;padding:13px}.login-card button{width:100%}.error{height:18px;color:#ff7180;font-size:11px}.print-note{color:var(--muted);font-size:11px;padding:0 16px 15px}@media(max-width:1100px){.stats{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.cards{grid-template-columns:1fr 1fr}.products{grid-template-columns:1fr 1fr}.side{display:none}.layout{display:block}}@media(max-width:650px){main{padding:15px}.stats,.cards,.products,.form-grid{grid-template-columns:1fr}.welcome{flex-direction:column;align-items:start}.search{width:100%}.detail-grid{grid-template-columns:1fr}.top{padding:0 12px}}
/* V30 Smart Operations Board */
.smart-meta{display:flex;gap:6px;flex-wrap:wrap;margin-top:7px}.smart-badge{display:inline-flex;align-items:center;gap:4px;padding:4px 7px;border-radius:999px;background:#112b3d;border:1px solid #23485e;color:#b9d1df;font-size:9px}.smart-badge.urgent{background:#5a1e2b;border-color:#8c3144;color:#ff9baa}.smart-badge.ok{background:#0b3c2c;border-color:#176b4d;color:#75e9b1}.smart-badge.wait{background:#4a350e;border-color:#72551a;color:#ffd66c}.smart-item{border:1px solid #24485d;border-radius:12px;padding:10px;background:linear-gradient(145deg,#0d2332,#091824);cursor:pointer;transition:.15s}.smart-item:hover{transform:translateY(-1px);border-color:#3b6d8a}.smart-item .topline{display:flex;align-items:center;justify-content:space-between;gap:8px}.smart-item .customer{font-weight:800}.smart-item .next{font-size:10px;color:#6bdcff;margin-top:7px}.smart-item .timer{font-size:10px;color:#8fa8b8}.order-cockpit{margin-top:16px;border:1px solid var(--line);border-radius:16px;background:#081824;padding:13px}.stepper{display:grid;grid-template-columns:repeat(6,1fr);gap:6px}.step{text-align:center;padding:9px 5px;border:1px solid #173047;border-radius:10px;background:#091724;color:#71889a;font-size:9px}.step.done{background:#0b3c2c;border-color:#176b4d;color:#75e9b1}.step.current{background:#123d5b;border-color:#3b84b0;color:#fff;box-shadow:0 0 0 2px #2d8cff22}.step.blocked{opacity:.55}.step small{display:block;margin-top:4px;font-size:8px}.next-action{margin-top:10px;padding:10px 12px;border-radius:11px;background:#102b3d;border:1px solid #24485d;display:flex;justify-content:space-between;align-items:center;gap:10px}.next-action b{color:#fff}.next-action span{color:#8fa8b8;font-size:10px}.sla-dot{width:7px;height:7px;border-radius:50%;display:inline-block;background:#62e8a9;margin-left:4px}.sla-dot.hot{background:#ff687a;box-shadow:0 0 0 5px #ff687a18}.sla-dot.wait{background:#ffd05c}@media(max-width:650px){.stepper{grid-template-columns:repeat(3,1fr)}.next-action{align-items:flex-start;flex-direction:column}}
</style></head><body>
<div id="login" class="login"><div class="login-card"><div class="brand-logo" style="margin:auto">SG</div><h2>Sea Gull Admin</h2><p style="color:var(--muted)">لوحة إدارة الطلبات والمبيعات — تسجيل الدخول محفوظ على هذا الجهاز</p><input id="loginUser" autocomplete="username" placeholder="اسم المستخدم (admin / owner)"><input id="loginKey" type="password" autocomplete="current-password" placeholder="كلمة المرور"><div id="loginErr" class="error"></div><button class="btn primary" onclick="login()">دخول لوحة التحكم</button></div></div>
<div id="app" style="display:none"><header class="top"><div class="brand"><div class="brand-logo">SG</div><div><b>Sea Gull</b><small>Restaurant Admin Pro</small></div></div><div class="branch-title" id="branchTitle" style="font-weight:800;color:#67d8ff"></div><div class="top-actions"><button class="btn" onclick="toggleAdminLang()">🌐 EN</button><button class="btn" onclick="loadOrders(true)">↻ تحديث</button><button class="btn red" onclick="logout()">خروج</button></div></header><div class="layout"><aside class="side"><div class="nav"><button id="ownerNav" data-page="owner" onclick="showPage('owner')" style="display:none">👑 الإدارة المركزية</button><button data-page="dashboard" onclick="showPage('dashboard')">🏠 الرئيسية</button><button data-page="orders" onclick="showPage('orders')">🧾 الطلبات <span id="navNew" class="pill red">0</span></button><button data-page="products" onclick="showPage('products')">🍽️ الأصناف والأسعار</button><button data-page="inventory" onclick="showPage('inventory')">📦 المخزون والجرد</button><button data-page="customers" onclick="showPage('customers')">👥 العملاء</button><button data-page="reports" onclick="showPage('reports')">📊 التقارير</button><button data-page="reviews" onclick="showPage('reviews')">⭐ التقييمات</button><button data-page="settings" onclick="showPage('settings')">⚙️ الإعدادات</button><button id="auditNav" data-page="audit" onclick="showPage('audit')" style="display:none">🛡️ سجل النشاط</button></div><div class="adminbox"><b>Sea Gull Admin</b><br><small>النظام جاهز لاستقبال الطلبات</small></div></aside><main>
<section id="page-owner" class="page"><div class="welcome"><div><h1>👑 الإدارة المركزية</h1><p>نظرة موحدة على جميع فروع Sea Gull</p></div></div><div class="stats"><div class="stat"><div class="label">طلبات اليوم — كل الفروع</div><div class="value" id="ownerOrders">0</div></div><div class="stat"><div class="label">مبيعات اليوم</div><div class="value" id="ownerSales">0</div></div><div class="stat"><div class="label">طلبات جديدة</div><div class="value" id="ownerNew">0</div></div><div class="stat"><div class="label">الفروع</div><div class="value" id="ownerBranchCount">0</div></div><div class="stat"><div class="label">💰 قيمة المخزون الحالي</div><div class="value" id="ownerStockValue">0</div></div><div class="stat"><div class="label">🔴 مكونات تحت حد التنبيه</div><div class="value" id="ownerLowStock">0</div></div></div><div class="panel" style="margin-top:16px"><div class="panel-head"><h2>أداء الفروع اليوم</h2><button class="btn" onclick="loadOwner()">↻ تحديث</button></div><div class="table-wrap"><table class="orders"><thead><tr><th>الفرع</th><th>الطلبات</th><th>المبيعات</th><th>طلبات جديدة</th><th>الحالة</th><th>إدارة</th></tr></thead><tbody id="ownerBranches"></tbody></table></div></div><div class="panel" style="margin-top:16px"><div class="panel-head"><h2>🛡️ أدوات المالك</h2></div><div style="padding:16px;display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" onclick="showPage('reports')">📊 التقارير المركزية</button><button class="btn" onclick="loadOrders(true)">🧾 كل الطلبات</button><button class="btn" onclick="showPage('products')">🍽️ إدارة المنيو المركزية</button><button class="btn" onclick="showPage('settings')">⚙️ إعدادات النظام</button><button class="btn" onclick="showPage('audit')">🛡️ سجل النشاط</button></div></div><div class="panel" style="margin-top:16px"><div class="panel-head"><h2>🏢 إدارة الفروع — الفتح/الإغلاق، المواعيد، كلمة مرور الدخول، ومنيو كل فرع</h2><button class="btn" onclick="loadOwnerBranchesFull()">↻ تحديث</button></div><div class="table-wrap"><table class="orders"><thead><tr><th>الفرع</th><th>الحالة</th><th>مواعيد العمل</th><th>الموقع</th><th>إجراءات</th></tr></thead><tbody id="branchMgmtRows"></tbody></table></div></div><div class="panel" style="margin-top:16px"><div class="panel-head"><h2>👥 حسابات موظفي الفروع (مدير/كاشير/مطبخ/دليفري)</h2><button class="btn primary" onclick="openStaffModal()">➕ حساب جديد</button></div><div class="table-wrap"><table class="orders"><thead><tr><th>اسم المستخدم</th><th>الاسم</th><th>الدور</th><th>الفرع</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody id="staffRows"></tbody></table></div></div></section><section id="page-dashboard" class="page active"><div class="welcome"><div><h1>لوحة التحكم</h1><p>متابعة مباشرة للطلبات والمبيعات</p></div><span style="color:#65e6a8">● Live</span> <span id="liveStatus" style="color:#9eb2c1;font-size:12px;margin-inline-start:8px">لسه منتظر أول فحص…</span></div><div class="stats"><div class="stat"><div class="label">طلبات اليوم</div><div id="sOrders" class="value">0</div><div class="sub">كل حالات الطلب</div></div><div class="stat"><div class="label">مبيعات اليوم</div><div id="sSales" class="value">0 ج.م</div><div class="sub">بعد الخصم</div></div><div class="stat"><div class="label">طلبات جديدة</div><div id="sNew" class="value">0</div><div class="sub">تحتاج انتباهك</div></div><div class="stat"><div class="label">متوسط الطلب</div><div id="sAvg" class="value">0 ج.م</div><div class="sub">متوسط قيمة الأوردر</div></div></div><section class="panel" style="margin-top:16px"><div class="panel-head"><h2>⚡ طوابير التشغيل</h2><button class="btn" onclick="loadOrders(true)">↻ تحديث</button></div><div class="action-queues"><div class="action-queue"><div class="action-queue-head"><span>🆕 طلبات جديدة</span><span id="qNewCount" class="action-count hot">0</span></div><div id="qNew" class="action-queue-body"></div></div><div class="action-queue"><div class="action-queue-head"><span>⚖️ تحتاج وزن/تسعير</span><span id="qPriceCount" class="action-count">0</span></div><div id="qPrice" class="action-queue-body"></div></div><div class="action-queue"><div class="action-queue-head"><span>⏳ تنتظر موافقة العميل</span><span id="qCustomerCount" class="action-count">0</span></div><div id="qCustomer" class="action-queue-body"></div></div><div class="action-queue"><div class="action-queue-head"><span>🚀 جاهزة للتجهيز</span><span id="qReadyCount" class="action-count">0</span></div><div id="qReady" class="action-queue-body"></div></div></div></section><div class="grid"><section class="panel"><div class="panel-head"><h2>آخر الطلبات</h2><button class="btn" onclick="showPage('orders')">عرض الكل</button></div><div class="table-wrap"><table class="orders"><thead><tr><th>الطلب</th><th>العميل</th><th>الهاتف</th><th>الإجمالي</th><th>الدفع</th><th>الحالة</th><th></th></tr></thead><tbody id="dashRows"></tbody></table></div></section><section class="panel"><div class="panel-head"><h2>🔴 تنبيهات المخزون</h2><button class="btn" onclick="showPage('inventory')">فتح المخزون</button></div><div id="dashStockAlerts" class="queue"></div></section></div></section>
<section id="page-orders" class="page"><div class="welcome"><div><h1>الطلبات</h1><p>عرض وطباعة وإدارة كل الأوردرات</p></div></div><section class="panel"><div class="panel-head"><h2>كل الطلبات</h2><div class="filters"><input id="search" class="search" placeholder="بحث بالاسم أو رقم الطلب أو الهاتف" oninput="renderOrders()"><select id="filter" class="select" onchange="renderOrders()"><option value="all">كل الحالات</option><option value="new">جديد</option><option value="accepted">مقبول</option><option value="preparing">قيد التحضير</option><option value="ready">جاهز</option><option value="out_for_delivery">خرج للتوصيل</option><option value="delivered">تم التسليم</option><option value="cancelled">ملغي</option></select></div></div><div class="table-wrap"><table class="orders"><thead><tr><th>الطلب</th><th>العميل</th><th>الهاتف</th><th>العنوان</th><th>الإجمالي</th><th>الدفع</th><th>الحالة</th><th>الإجراءات</th></tr></thead><tbody id="orderRows"></tbody></table></div></section></section>
<section id="page-products" class="page"><div class="welcome"><div><h1>الأصناف والأسعار</h1><p>اضغط على اسم القسم لفتح/طي أصنافه، واضغط على أي صنف لتعديل كل تفاصيله (السعر، الوصف، طرق التحضير، الوصفة).</p></div><div><button class="btn primary" onclick="openItem()">＋ إضافة صنف</button> <button class="btn" onclick="openCat()">＋ إضافة قسم</button></div></div><section class="panel"><div class="panel-head"><h2>المنيو</h2><input id="productSearch" class="search" placeholder="ابحث عن صنف" oninput="renderProducts()"></div><div id="productsGrid"></div></section></section>
<section id="page-inventory" class="page"><div class="welcome"><div><h1>🧂 المخزون والجرد الحقيقي</h1><p>مكونات خام بكمياتها الفعلية، مربوطة تلقائيًا بوصفة كل صنف — كل عملية بيع تخصم من المخزون أوتوماتيك، وأي إلغاء يرجّع الكمية.</p></div><button class="btn primary" onclick="openIngredientModal()">➕ مكوّن جديد</button></div>
<section class="panel"><div class="panel-head"><h2>المكونات الخام</h2><button class="btn" onclick="loadIngredients()">↻ تحديث</button></div><div class="table-wrap"><table class="orders"><thead><tr><th>المكوّن</th><th>الرصيد الحالي</th><th>الوحدة</th><th>حد التنبيه</th><th>تكلفة/وحدة</th><th>الحالة</th><th>إجراءات</th></tr></thead><tbody id="ingredientRows"></tbody></table></div></section>
<section class="panel" style="margin-top:16px"><div class="panel-head"><h2>📒 سجل حركة المخزون (آخر الحركات)</h2><button class="btn" onclick="loadIngredientMovements()">↻ تحديث</button></div><div class="table-wrap"><table class="orders"><thead><tr><th>المكوّن</th><th>الكمية</th><th>السبب</th><th>بواسطة</th><th>التاريخ</th></tr></thead><tbody id="movementRows"></tbody></table></div></section>
<section class="panel" style="margin-top:16px"><div class="panel-head"><h2>القديم: توفر الصنف كاملًا (بدون وصفة)</h2></div><div class="table-wrap"><table class="orders"><thead><tr><th>الصنف</th><th>القسم</th><th>المخزون</th><th>الوحدة</th><th>حد التنبيه</th><th>حالة</th><th>حفظ</th></tr></thead><tbody id="inventoryRows"></tbody></table></div></section></section><section id="page-customers" class="page"><div class="welcome"><div><h1>العملاء</h1><p>ملخص تاريخ الطلبات لكل عميل.</p></div></div><section class="panel"><div style="display:flex;gap:10px;flex-wrap:wrap;padding:14px 16px 0"><input id="custSearch" class="search" placeholder="🔍 بحث بالاسم أو رقم الهاتف" style="flex:1;min-width:220px" oninput="renderCustomersFiltered()"><input id="custDay" type="date" class="search" style="width:170px" onchange="renderCustomersFiltered()"><button class="btn" onclick="document.getElementById('custSearch').value='';document.getElementById('custDay').value='';renderCustomersFiltered()">✕ مسح الفلتر</button></div><div class="table-wrap"><table class="orders"><thead><tr><th>العميل</th><th>الهاتف</th><th>العنوان</th><th>عدد الطلبات</th><th>إجمالي الإنفاق</th><th>آخر طلب</th></tr></thead><tbody id="customerRows"></tbody></table></div></section></section>
<section id="page-reports" class="page"><div class="welcome"><div><h1>التقارير</h1><p>حدد فترة من يوم إلى يوم، واطبع التقرير.</p></div></div><section class="panel"><div class="report-tools"><div class="field"><label>من</label><input id="from" type="date"></div><div class="field"><label>إلى</label><input id="to" type="date"></div><button class="btn primary" onclick="loadReport()">عرض التقرير</button><button class="btn" onclick="printReport()">🖨 طباعة التقرير</button><button class="btn" onclick="downloadReportCSV()">⬇️ Excel/CSV</button></div><div id="reportSummary" class="cards" style="padding:0 15px 15px"></div><div class="table-wrap" style="padding:15px"><h3>حركة الطلبات</h3><table class="report-table"><tbody id="reportStatus"></tbody></table><h3>طرق الدفع</h3><table class="report-table"><tbody id="reportPay"></tbody></table><h3>تقرير الأصناف والكميات والأوزان</h3><table class="report-table"><thead><tr><th>الصنف</th><th>الكمية</th><th>الوزن</th><th>المبيعات</th></tr></thead><tbody id="reportItems"></tbody></table></div></section></section>
<section id="page-reviews" class="page"><div class="welcome"><div><h1>التقييمات</h1><p>مراجعات العملاء وتقييم الخدمة والمطعم.</p></div></div><section class="panel"><div id="adminReviews" class="products"></div></section></section>
<section id="page-audit" class="page"><div class="welcome"><div><h1>🛡️ سجل النشاط</h1><p>سجل مركزي للعمليات المهمة — متاح للمالك فقط.</p></div><button class="btn" onclick="loadAudit()">↻ تحديث</button></div><section class="panel"><div class="table-wrap"><table class="orders"><thead><tr><th>الوقت</th><th>العملية</th><th>رقم الطلب</th><th>التفاصيل</th></tr></thead><tbody id="auditRows"></tbody></table></div></section></section><section id="page-settings" class="page"><div class="welcome"><div><h1>الإعدادات الذكية</h1><p>كل إعدادات الموقع في مكان واحد.</p></div></div><section class="panel"><div class="form-grid"><div class="field"><label>رقم WhatsApp للتواصل</label><input id="setWhatsapp"></div><div class="field"><label>رقم WhatsApp الدليفري</label><input id="setDriverWhatsapp" placeholder="مثال: 010xxxxxxxx"></div><div class="field"><label>صوت إنذار الطلب الجديد</label><input id="setAlertVolume" type="number" min="0.03" max="0.4" step="0.01"></div><div class="field"><label>🔊 نغمة إنذار الطلب الجديد</label><small style="display:block;color:#91a6b7;margin-top:5px">نغمة ثابتة لكل الفروع — لا يمكن تغييرها من هنا لضمان سماعها دايمًا.</small><div style="margin-top:8px"><button class="btn" type="button" onclick="testAlertSound()">▶️ تجربة النغمة</button></div></div><div class="field"><label>خصم الأونلاين %</label><input id="setDiscount" type="number"></div><div class="field"><label>اسم الفرع</label><input id="setBranch"></div><div class="field"><label>تحديث لوحة التحكم بالثواني</label><input id="setRefresh" type="number"></div><div class="field"><label>فتح الموقع</label><input id="setOpen" type="time"></div><div class="field"><label>إغلاق الموقع</label><input id="setClose" type="time"></div><div class="field"><label>حساب InstaPay / رقم التحويل</label><input id="setInsta"></div><div class="field"><label>رقم المحفظة الإلكترونية</label><input id="setWalletNumber"></div><div class="field"><label>طباعة الأوردر تلقائيًا</label><select id="setAutoPrint"><option value="1">مفعلة</option><option value="0">متوقفة</option></select></div><div class="field"><label>Instagram</label><input id="setInstagram"></div><div class="field"><label>Facebook</label><input id="setFacebook"></div><div class="field"><label>الدفع عند الاستلام</label><select id="payCash"><option value="1">مفعل</option><option value="0">متوقف</option></select></div><div class="field"><label>Visa / فيزا</label><select id="payVisa"><option value="1">مفعل</option><option value="0">متوقف</option></select></div><div class="field"><label>InstaPay</label><select id="payInsta"><option value="1">مفعل</option><option value="0">متوقف</option></select></div><div class="field"><label>المحفظة الإلكترونية</label><select id="payWallet"><option value="1">مفعل</option><option value="0">متوقف</option></select></div></div><div style="padding:0 16px 16px"><button class="btn primary" onclick="saveSettings()">💾 حفظ كل الإعدادات</button> <button class="btn green" onclick="downloadBackup()">💾 نسخة احتياطية كاملة</button> <button class="btn red" id="ownerResetBtn" onclick="resetData()">👑 تصفير بيانات جميع الفروع</button></div><div id="ownerCredsBox" class="panel" style="margin:0 16px 16px;display:none"><div class="panel-head"><h2>👑 بيانات دخول المالك (Owner)</h2></div><div class="form-grid"><div class="field"><label>كلمة المرور الحالية</label><input id="ocCurrent" type="password"></div><div class="field"><label>اسم مستخدم جديد</label><input id="ocUsername" placeholder="owner"></div><div class="field"><label>كلمة مرور جديدة</label><input id="ocPassword" type="password" placeholder="6 حروف/أرقام على الأقل"></div></div><div style="padding:0 16px 16px"><button class="btn primary" onclick="saveOwnerCreds()">💾 تحديث بيانات الدخول</button></div></div><div class="print-note">التصفير متاح للـOwner فقط، ويمسح الطلبات والتقييمات من جميع الفروع. لا يمسح المنيو أو الأسعار.
• لو العميل شارك موقعه، سيظهر لك زر فتح الخريطة وزر تجهيز رسالة واتساب للدليفري.</div></section></section>
</main></div></div><div id="alarm" class="alarm"></div><div id="toast" class="toast"></div><div id="audioBlockedBanner" onclick="retryUnlockAudio()" style="display:none;position:fixed;top:0;left:0;right:0;z-index:99999;background:#c0392b;color:#fff;text-align:center;padding:14px;font-weight:900;font-size:15px;cursor:pointer">🔇 المتصفح مانع صوت التنبيه — دوس هنا فورًا لتفعيله</div>
<div id="ingredientModal" class="modal-backdrop" onclick="if(event.target===this)closeIngredientModal()"><div class="modal"><div class="modal-head"><b id="ingredientModalTitle">مكوّن جديد</b><button class="mini" onclick="closeIngredientModal()">✕</button></div><div class="modal-body"><input type="hidden" id="ingId"><div class="form-grid"><div class="field"><label>اسم المكوّن (عربي)</label><input id="ingNameAr"></div><div class="field"><label>Name (English)</label><input id="ingNameEn"></div><div class="field"><label>الوحدة</label><select id="ingUnit"><option value="g">جرام (g)</option><option value="kg">كيلو (kg)</option><option value="ml">مل (ml)</option><option value="l">لتر (l)</option><option value="pcs">قطعة (pcs)</option></select></div><div class="field"><label>حد التنبيه (Reorder level)</label><input id="ingReorder" type="number" min="0" step="0.1" value="0"></div><div class="field"><label>تكلفة الوحدة (اختياري)</label><input id="ingCost" type="number" min="0" step="0.1" value="0"></div></div><div class="modal-actions"><button class="btn primary" onclick="saveIngredientModal()">💾 حفظ</button></div></div></div></div>
<div id="restockModal" class="modal-backdrop" onclick="if(event.target===this)closeRestockModal()"><div class="modal"><div class="modal-head"><b>تسجيل حركة مخزون</b><button class="mini" onclick="closeRestockModal()">✕</button></div><div class="modal-body"><input type="hidden" id="rsIngId"><div class="form-grid"><div class="field"><label>الكمية (موجب = إضافة / سالب = خصم يدوي)</label><input id="rsQty" type="number" step="0.1"></div><div class="field"><label>السبب</label><input id="rsReason" placeholder="مثال: توريد جديد / هالك / جرد فعلي"></div></div><div class="modal-actions"><button class="btn primary" onclick="saveRestockModal()">💾 تسجيل</button></div></div></div></div>
<div id="branchModal" class="modal-backdrop" onclick="if(event.target===this)closeBranchModal()"><div class="modal"><div class="modal-head"><b id="branchModalTitle">تعديل بيانات الفرع</b><button class="mini" onclick="closeBranchModal()">✕</button></div><div class="modal-body"><input type="hidden" id="bmBranchId"><div class="form-grid"><div class="field"><label>خط العرض Lat</label><input id="bmLat" type="number" step="0.000001"></div><div class="field"><label>خط الطول Lng</label><input id="bmLng" type="number" step="0.000001"></div><div class="field"><label>وقت الفتح</label><input id="bmOpen" type="time"></div><div class="field"><label>وقت الإغلاق</label><input id="bmClose" type="time"></div><div class="field"><label>كلمة مرور دخول الفرع الجديدة</label><input id="bmPassword" placeholder="اتركها فارغة لعدم التغيير"></div></div><div class="modal-actions"><button class="btn primary" onclick="saveBranchModal()">💾 حفظ</button> <button class="btn" onclick="closeBranchModal();openBranchMenuModal(document.getElementById('bmBranchId').value)">🍽️ منيو هذا الفرع</button></div></div></div></div>
<div id="branchMenuModal" class="modal-backdrop" onclick="if(event.target===this)closeBranchMenuModal()"><div class="modal"><div class="modal-head"><b>تخصيص منيو الفرع (التوافر والسعر)</b><button class="mini" onclick="closeBranchMenuModal()">✕</button></div><div class="modal-body"><div style="margin-bottom:10px"><button class="btn red" onclick="resetBranchMenuOverrides()">↺ إعادة كل الأصناف للسعر والتوافر الأساسي</button></div><div id="branchMenuItems" class="products"></div></div></div></div>
<div id="staffModal" class="modal-backdrop" onclick="if(event.target===this)closeStaffModal()"><div class="modal"><div class="modal-head"><b id="staffModalTitle">حساب جديد</b><button class="mini" onclick="closeStaffModal()">✕</button></div><div class="modal-body"><input type="hidden" id="stId"><div class="form-grid"><div class="field"><label>اسم المستخدم</label><input id="stUsername"></div><div class="field"><label>كلمة المرور</label><input id="stPassword" type="password" placeholder="اتركها فارغة لعدم التغيير عند التعديل"></div><div class="field"><label>الاسم الظاهر</label><input id="stDisplay"></div><div class="field"><label>الدور</label><select id="stRole"><option value="manager">مدير فرع</option><option value="cashier">كاشير</option><option value="kitchen">مطبخ</option><option value="delivery">دليفري</option></select></div><div class="field"><label>الفرع</label><select id="stBranch"></select></div><div class="field"><label>الحالة</label><select id="stActive"><option value="1">مفعل</option><option value="0">موقوف</option></select></div></div><div class="modal-actions"><button class="btn primary" onclick="saveStaffModal()">💾 حفظ</button></div></div></div></div>
<div id="modal" class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><b id="modalTitle">التفاصيل</b><button class="btn" onclick="closeModal()">✕</button></div><div id="modalBody" class="modal-body"></div></div></div>
<script>
let key=localStorage.sgkey||'',orders=[],menu={cats:{},icons:{},items:[]},settings={},lastNewIds=new Set(),alarmOn=false,audioCtx=null,alertAudio=null,reportData=null,currentOrderId=null,initialOrdersLoaded=false,lastPollAt=0,printWindow=null;
let adminLang=localStorage.sgAdminLang||'ar';
function getCookie(n){const m=document.cookie.match(new RegExp('(?:^|; )'+n.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'=([^;]*)'));return m?decodeURIComponent(m[1]):''}
function persistKey(k){localStorage.setItem('sgkey',k);localStorage.setItem('sgLoginAt',String(Date.now()));document.cookie='sg_auth='+encodeURIComponent(k)+'; Max-Age=31536000; Path=/; SameSite=Lax'}
if(!key) key=getCookie('sg_auth')||'';
let statusNames=adminLang==='en'?{new:'New',accepted:'Accepted',preparing:'Preparing',ready:'Ready',out_for_delivery:'Out for delivery',delivered:'Delivered',cancelled:'Cancelled'}:{new:'جديد',accepted:'مقبول',preparing:'قيد التحضير',ready:'جاهز',out_for_delivery:'خرج للتوصيل',delivered:'تم التسليم',cancelled:'ملغي'};
const _nativeFetch=window.fetch.bind(window);window.fetch=(url,opts={})=>{opts=opts||{};opts.credentials='include';return _nativeFetch(url,opts)};
function esc(x){return String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}function money(x){return Number(x||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})+' ج.م'}
function isWeightItem(i){
  if(i?.pricing_mode) return i.pricing_mode==='weight';
  return parseRequestedWeight(i)>0;
}
function parseRequestedWeight(i){
  const w=Number(i?.weight);
  if(w>0) return w;
  if(i?.choice){
    const m=String(i.choice).match(/([\d.]+)/);
    if(m){const kg=parseFloat(m[1]);if(!isNaN(kg)&&kg>0) return Math.round(kg*1000);}
  }
  return 0;
}
function fmtGrams(g){
  g=Number(g)||0;
  if(g<=0) return '-';
  if(g>=1000){const kg=g/1000;return (Number.isInteger(kg)?kg:kg.toFixed(3).replace(/0+$/,'').replace(/\.$/,''))+' كجم';}
  return g+' جم';
}
function showPage(page){
  if(page==='owner' && window.sgRole!=='owner'){toast('هذه الصفحة للمالك فقط');return;}
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
  const target=document.getElementById('page-'+page);
  if(!target){toast('القسم غير متاح');return;}
  target.classList.add('active');
  document.querySelectorAll('.nav button[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
  if(page==='owner') loadOwner();
  if(page==='orders') loadOrders();
  if(page==='products') renderProducts();
  if(page==='inventory'){loadInventory();loadIngredients();loadIngredientMovements();}
  if(page==='customers') loadCustomers();
  if(page==='reports') loadReport();
  if(page==='reviews') loadReviewsAdmin();
  if(page==='settings') loadSettings();
  if(page==='audit') loadAudit();
}
function toast(t){const e=document.getElementById('toast');e.textContent=t;e.style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>e.style.display='none',2600)}
async function login(){const u=document.getElementById('loginUser').value.trim(),k=document.getElementById('loginKey').value.trim();if(!u||!k)return;try{if(typeof unlockAlarmAudio==='function')unlockAlarmAudio(true);}catch(e){console.warn('unlockAlarmAudio failed, continuing login anyway',e);}const btn=document.querySelector('#login .login-card button.primary');const errBox=document.getElementById('loginErr');errBox.textContent='';const prevText=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent='⏳ جاري تسجيل الدخول...';}const ctrl=new AbortController();const timeoutId=setTimeout(()=>ctrl.abort(),20000);try{const r=await fetch('api.php?action=admin_login',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({username:u,password:k}),signal:ctrl.signal});clearTimeout(timeoutId);const d=await r.json();if(!d.ok){errBox.textContent='اسم المستخدم أو كلمة المرور غير صحيحة';return}key=k;window.sgRole=d.role;window.sgBranchId=d.branch_id;window.sgBranchName=d.branch_name;localStorage.setItem('sgLoginAt',String(Date.now()));document.getElementById('login').style.display='none';document.getElementById('app').style.display='block';applyIdentity(d);prepareLiveAlerts();start()}catch(e){clearTimeout(timeoutId);errBox.textContent=e.name==='AbortError'?'⚠️ السيرفر بياخد وقت طويل جدًا في الرد (أكتر من 20 ثانية) — جرب تاني أو كلم الاستضافة':'تعذر الاتصال بالسيرفر'}finally{if(btn){btn.disabled=false;btn.textContent=prevText;}}}
function applyIdentity(d){
  window.sgRole=d.role||'branch';
  window.sgBranchId=d.role==='owner'?'':(d.branch_id||'');
  window.sgBranchName=d.role==='owner'?'الإدارة المركزية — كل الفروع':(d.branch_name||'');
  document.getElementById('branchTitle').textContent=d.role==='owner'?'👑 الإدارة المركزية — كل الفروع':'🏪 لوحة تحكم '+d.branch_name;
  document.querySelector('.adminbox').innerHTML=`<b>${esc(d.role==='owner'?'Super Admin':d.branch_name)}</b><br><small>${d.role==='owner'?'صلاحيات كاملة على جميع الفروع':'صلاحيات هذا الفرع فقط'}</small>`;
  document.getElementById('ownerNav').style.display=d.role==='owner'?'flex':'none';
  document.getElementById('auditNav').style.display=d.role==='owner'?'flex':'none'; const rb=document.getElementById('ownerResetBtn'); if(rb) rb.style.display=d.role==='owner'?'inline-block':'none';
  if(d.role==='owner'){showPage('owner');loadOwner();} else {showPage('dashboard');}
}
async function loadOwner(){if(window.sgRole!=='owner')return;const r=await fetch('api.php?action=owner_dashboard',{credentials:'include',cache:'no-store'});const d=await r.json();if(!d.ok)return;document.getElementById('ownerOrders').textContent=d.summary.orders_count||0;document.getElementById('ownerSales').textContent=money(d.summary.sales||0);document.getElementById('ownerNew').textContent=d.summary.new_orders||0;document.getElementById('ownerBranchCount').textContent=(d.branches||[]).length;
 if(!INGREDIENTS_CACHE.length) await loadIngredients();
 const stockValue=INGREDIENTS_CACHE.reduce((s,i)=>s+Number(i.stock||0)*Number(i.cost_per_unit||0),0);
 document.getElementById('ownerStockValue').textContent=money(stockValue);
 document.getElementById('ownerLowStock').textContent=INGREDIENTS_CACHE.filter(i=>Number(i.low)).length;document.getElementById('ownerBranches').innerHTML=d.branches.map(b=>`<tr><td><b>${esc(b.name)}</b></td><td>${b.orders_count||0}</td><td>${money(b.sales||0)}</td><td>${b.new_orders||0}</td><td>${Number(b.active??1)?'🟢 مفتوح':'🔴 مغلق'}</td><td><button class="mini" onclick="resetBranchData('${esc(b.id)}','${esc(b.name)}')">🧹 تصفير الفرع</button></td></tr>`).join('');await loadOwnerBranchesFull();await loadStaffList()}
async function logout(){try{await fetch('api.php?action=admin_logout',{credentials:'include'});}catch(e){}localStorage.removeItem('sgkey');localStorage.removeItem('sgLoginAt');location.reload()}
async function checkAdminSession(){try{const r=await fetch('api.php?action=admin_session',{credentials:'include',cache:'no-store'});const d=await r.json();if(d.ok){window.sgRole=d.user.role;window.sgBranchId=d.user.branch_id;window.sgBranchName=d.user.branch_name;document.getElementById('login').style.display='none';document.getElementById('app').style.display='block';applyIdentity(d.user);prepareLiveAlerts();start();return true}}catch(e){}return false}
function applyOrdersData(list,manual=false){const previous=new Set(lastNewIds);orders=Array.isArray(list)?list:[];const newOrders=orders.filter(o=>String(o.status)==='new');document.getElementById('navNew').textContent=newOrders.length;renderDashboard();renderOrders();if(manual)toast('تم تحديث الطلبات');const ids=new Set(newOrders.map(o=>String(o.id)));if(initialOrdersLoaded){const unseen=[...ids].filter(id=>!previous.has(id));if(unseen.length){startAlarm();if(String(settings.auto_print||'1')==='1')unseen.slice(0,3).forEach(id=>setTimeout(()=>autoPrintOrder(Number(id)),250));}}else{initialOrdersLoaded=true;}lastNewIds=ids;lastPollAt=Date.now()}
async function loadOrders(manual=false){try{const r=await fetch('api.php?action=list_orders&_='+Date.now(),{credentials:'include',cache:'no-store',headers:{'Cache-Control':'no-cache'}});const d=await r.json();if(!d.ok){if(String(d.error||'').toLowerCase()==='unauthorized'){document.getElementById('loginErr').textContent='انتهت جلسة الإدارة';document.getElementById('login').style.display='grid';document.getElementById('app').style.display='none';}return}applyOrdersData(d.orders,manual)}catch(e){console.warn('orders poll failed',e)}}
function renderDashboard(){const today=new Date().toISOString().slice(0,10);const td=orders.filter(o=>String(o.created_at).slice(0,10)===today);const news=td.filter(o=>o.status==='new');const priceReview=td.filter(o=>Number(o.price_pending)===1);const waitingCustomer=td.filter(o=>Number(o.price_pending)===0&&!Number(o.customer_confirmed)&&!['preparing','ready','out_for_delivery','delivered','cancelled'].includes(o.status));const readyToPrep=td.filter(o=>Number(o.customer_confirmed)&&['accepted'].includes(o.status));const sales=td.reduce((s,o)=>s+Number(o.total||0),0);document.getElementById('sOrders').textContent=td.length;document.getElementById('sSales').textContent=money(sales);document.getElementById('sNew').textContent=news.length;document.getElementById('sAvg').textContent=money(td.length?sales/td.length:0);document.getElementById('dashRows').innerHTML=td.slice(0,8).map(o=>row(o,true)).join('')||'<tr><td colspan="7"><div style="padding:35px;text-align:center;color:var(--muted)">لا توجد طلبات اليوم</div></td></tr>';renderActionQueue('qNew','qNewCount',news,'🆕');renderActionQueue('qPrice','qPriceCount',priceReview,'⚖️');renderActionQueue('qCustomer','qCustomerCount',waitingCustomer,'⏳');renderActionQueue('qReady','qReadyCount',readyToPrep,'🚀');renderStockAlerts()}
function renderStockAlerts(){const box=document.getElementById('dashStockAlerts');if(!box)return;const low=(INGREDIENTS_CACHE||[]).filter(i=>Number(i.low));box.innerHTML=low.length?low.map(i=>`<div class="q"><div class="qtop"><b>${esc(i.name_ar)}</b><span>${Number(i.stock).toLocaleString('en-US',{maximumFractionDigits:2})} ${esc(i.unit)}</span></div><div class="price" style="color:#ff8a8a">تحت حد التنبيه (${Number(i.reorder_level).toLocaleString('en-US',{maximumFractionDigits:2})} ${esc(i.unit)})</div><button class="mini" style="margin-top:7px" onclick="showPage('inventory')">فتح المخزون وتوريد</button></div>`).join(''):'<div style="color:var(--muted);padding:20px">لا توجد نواقص حاليًا 🎉</div>'}
function nextActionText(o){if(o.status==='new')return Number(o.price_pending)?'راجع الوزن واعتمد السعر ثم أرسله للعميل':'ابدأ قبول الطلب';if(o.status==='accepted')return Number(o.customer_confirmed)?'ابدأ التجهيز':'في انتظار موافقة العميل';if(o.status==='preparing')return 'سجّل الطلب كجاهز';if(o.status==='ready')return 'سلّم الطلب للدليفري';if(o.status==='out_for_delivery')return 'أكد التسليم';return o.status==='delivered'?'اكتمل الطلب':'لا يوجد إجراء';}
function elapsedText(ts){if(!ts)return '';const t=new Date(String(ts).replace(' ','T'));if(Number.isNaN(t.getTime()))return '';let m=Math.max(0,Math.floor((Date.now()-t.getTime())/60000));if(m<60)return m+' د';const h=Math.floor(m/60);return h+' س '+(m%60)+' د';}
function urgencyClass(o){if(['delivered','cancelled'].includes(o.status))return 'ok';const d=new Date(String(o.created_at||'').replace(' ','T'));const mins=Number.isNaN(d.getTime())?0:Math.floor((Date.now()-d.getTime())/60000);if(o.status==='new'&&mins>=10)return 'urgent';if(o.status==='accepted'&&Number(o.customer_confirmed)&&mins>=20)return 'urgent';return 'wait';}
function renderActionQueue(target,countId,list,icon){const el=document.getElementById(target),count=document.getElementById(countId);if(!el||!count)return;count.textContent=list.length;count.classList.toggle('hot',list.length>0&&target==='qNew');el.innerHTML=list.slice(0,12).map(o=>`<div class="smart-item" onclick="viewOrder(${o.id})"><div class="topline"><span class="customer"><b>#${esc(o.order_no)}</b> — ${esc(o.customer_name)}</span><span class="timer"><i class="sla-dot ${urgencyClass(o)}"></i>${elapsedText(o.created_at)}</span></div><div class="smart-meta"><span class="smart-badge">${money(o.total)} ج.م</span><span class="smart-badge">${esc(statusNames[o.status]||o.status)}</span></div><div class="next">→ ${nextActionText(o)}</div></div>`).join('')||'<div class="queue-empty">لا توجد طلبات هنا 👍</div>'}

function row(o,compact=false){return `<tr><td><span class="order-no">#${esc(o.order_no)}</span><div class="muted">أوردر رقم #${esc(o.daily_serial||'—')} · ${esc(o.created_at)}</div></td><td><b>${esc(o.customer_name)}</b>${compact?'':`<div class="muted">${esc(o.address)}</div>`}</td><td>${esc(o.phone)}</td>${compact?'':`<td>${esc(o.address)}</td>`}<td class="money">${money(o.total)}</td>${compact?`<td>${payName(o.payment)}</td>`:`<td>${payName(o.payment)}</td>`}<td><span class="status ${esc(o.status)}">${statusNames[o.status]||o.status}</span></td><td><div class="actions"><button class="mini" onclick="viewOrder(${o.id})">👁</button><button class="mini" onclick="printOrder(${o.id})">🖨</button>${o.location_url?`<button class="mini" onclick="openLocation(${o.id})">📍</button>`:''}<button class="mini" title="${esc(nextActionText(o))}" onclick="nextStatus(${o.id})">${o.status==='new'?'⚡':o.status==='accepted'?'▶️':o.status==='preparing'?'✅':o.status==='ready'?'🚚':o.status==='out_for_delivery'?'✓':'→'}</button></div></td></tr>`}
function payName(p){if(adminLang==='en')return p==='cash'?'Cash':p==='visa'?'Visa':p==='instapay'?'InstaPay':p==='wallet'?'E-Wallet':p;return p==='cash'?'كاش':p==='visa'?'فيزا':p==='instapay'?'InstaPay':p==='wallet'?'محفظة إلكترونية':p}
function renderOrders(){let q=(document.getElementById('search')?.value||'').toLowerCase(),f=document.getElementById('filter')?.value||'all';let a=orders.filter(o=>(f==='all'||o.status===f)&&(!q||[o.order_no,o.customer_name,o.phone,o.address].join(' ').toLowerCase().includes(q)));document.getElementById('orderRows').innerHTML=a.map(o=>row(o)).join('')||'<tr><td colspan="8"><div style="padding:40px;text-align:center;color:var(--muted)">لا توجد طلبات</div></td></tr>'}
function autoPrintOrder(id){const o=orders.find(x=>x.id==id);if(!o||o.status!=='new')return;const mark='sg_printed_'+id;if(localStorage.getItem(mark)==='1')return;const w=printOrder(id,true);if(w){localStorage.setItem(mark,'1');toast('🖨️ تم إرسال الأوردر للطباعة تلقائيًا');}}
function unlockAlarmAudio(force){try{if(!alertAudio){alertAudio=new Audio('order-chime.mp3');alertAudio.preload='auto';}if(!audioCtx&&(window.AudioContext||window.webkitAudioContext)){try{audioCtx=new (window.AudioContext||window.webkitAudioContext)();}catch(e){}}if(audioCtx&&audioCtx.state==='suspended'){audioCtx.resume().catch(()=>{});}if(force){const wasMuted=alertAudio.muted;alertAudio.muted=true;const p=alertAudio.play();if(p&&p.then){p.then(()=>{alertAudio.pause();alertAudio.currentTime=0;alertAudio.muted=wasMuted;}).catch(()=>{alertAudio.muted=wasMuted;});}}}catch(e){}}
function prepareLiveAlerts(){
  try{if(typeof unlockAlarmAudio==='function')unlockAlarmAudio(true);}catch(e){}
  if('Notification' in window && Notification.permission==='default'){Notification.requestPermission().catch(()=>{});}
  document.title=titleBase;
  requestWakeLock();
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){requestWakeLock();pollAdminEvents(false);loadOrders();}});
  window.addEventListener('focus',()=>{pollAdminEvents(false);loadOrders();});
}
let sgWakeLock=null;
async function requestWakeLock(){
  try{
    if('wakeLock' in navigator && document.visibilityState==='visible'){
      sgWakeLock=await navigator.wakeLock.request('screen');
      sgWakeLock.addEventListener('release',()=>{sgWakeLock=null;});
    }
  }catch(e){console.warn('wake lock unavailable',e);}
}
function startAlarm(){if(alarmOn)return;alarmOn=true;document.getElementById('alarm').classList.add('on');try{alertAudio=alertAudio||new Audio('order-chime.mp3');alertAudio.preload='auto';alertAudio.loop=true;alertAudio.volume=Math.max(.05,Math.min(1,Number(settings.alert_volume||0.16)));alertAudio.muted=false;const p=alertAudio.play();if(p&&p.catch)p.then(()=>{hideAudioBanner();}).catch((err)=>{console.warn('alarm audio blocked:',err);showAudioBanner();});}catch(e){console.warn('alarm audio threw:',e);showAudioBanner();}}
function showAudioBanner(){const b=document.getElementById('audioBlockedBanner');if(b)b.style.display='block';}
function hideAudioBanner(){const b=document.getElementById('audioBlockedBanner');if(b)b.style.display='none';}
function retryUnlockAudio(){try{if(typeof unlockAlarmAudio==='function')unlockAlarmAudio(true);}catch(e){}hideAudioBanner();if(alarmOn){alarmOn=false;startAlarm();}else{try{alertAudio=alertAudio||new Audio('order-chime.mp3');alertAudio.muted=false;alertAudio.volume=Math.max(.05,Math.min(1,Number(settings.alert_volume||0.16)));const p=alertAudio.play();if(p&&p.then)p.then(()=>{alertAudio.pause();alertAudio.currentTime=0;toast('✅ الصوت شغال دلوقتي');}).catch(()=>{toast('لسه محظور — جرب اضغط في أي حتة تانية بالصفحة الأول');});}catch(e){}}}
function stopAlarm(){alarmOn=false;document.getElementById('alarm').classList.remove('on');hideAudioBanner();try{if(alertAudio){alertAudio.pause();alertAudio.currentTime=0;}}catch(e){}}
function flashLiveTitle(){let n=0;const t=setInterval(()=>{document.title=(n++%2)?titleBase:'🔔 Sea Gull — تحديث جديد';if(n>7){clearInterval(t);document.title=titleBase}},500)}
function notifyEvent(ev){
  const action=String(ev.action||'');
  const map={order_created:'🆕 طلب جديد',customer_order_edited:'✏️ العميل عدّل الطلب',customer_price_confirmed:'✅ العميل أكد السعر',customer_order_cancelled:'❌ العميل ألغى الطلب',customer_cancel_requested:'🟠 العميل طلب إلغاء',customer_cancel_approved:'❌ تم اعتماد إلغاء العميل',delivery_fee_changed:'🚚 تم تعديل التوصيل',order_repriced:'⚖️ تم إعادة تسعير الطلب',receipt_uploaded:'🧾 تم رفع إيصال دفع'};
  const title=map[action]||'🔔 تحديث على طلب';
  const body=[ev.order_no?'#'+ev.order_no:'',ev.customer_name||'',ev.details||''].filter(Boolean).join(' — ').slice(0,180);
  startAlarm();flashLiveTitle();toast(title+(body?' | '+body:''));
  try{if('Notification' in window && Notification.permission==='granted')new Notification('Sea Gull — '+title,{body,tag:'sg-'+ev.id});}catch(e){}
}
async function pollAdminEvents(initial=false){
 try{const r=await fetch('api.php?action=admin_events&after='+encodeURIComponent(lastEventId)+'&_='+Date.now(),{credentials:'include',cache:'no-store'});const d=await r.json();if(!d.ok)return;const evs=Array.isArray(d.events)?d.events:[];if(!evs.length)return;
   if(initial){lastEventId=Math.max(...evs.map(e=>Number(e.id)||0));eventBooted=true;return;}
   for(const ev of evs){lastEventId=Math.max(lastEventId,Number(ev.id)||0);notifyEvent(ev);}
 }catch(e){}
}
function startLiveSync(){
 if(window.sgLiveSyncStarted)return; window.sgLiveSyncStarted=true;
 pollAdminEvents(true);
 setInterval(()=>{ loadOrders(); pollAdminEvents(false); updateLiveStatus(); }, 4000);
 updateLiveStatus();
}
function updateLiveStatus(){const el=document.getElementById('liveStatus');if(el){const now=new Date();el.textContent='آخر فحص: '+now.toLocaleTimeString('ar-EG');}}
function viewOrder(id){stopAlarm();currentOrderId=id;const o=orders.find(x=>x.id==id);if(!o)return;const items=o.items||[];document.getElementById('modalTitle').textContent='🧾 مركز تشغيل الطلب · #'+o.order_no+' · أوردر رقم '+(o.daily_serial||'—');const steps=[['new','جديد'],['accepted','مقبول'],['preparing','تجهيز'],['ready','جاهز'],['out_for_delivery','توصيل'],['delivered','تم التسليم']];const si=steps.findIndex(x=>x[0]===o.status);const stepper=steps.map((x,i)=>`<div class="step ${i<si?'done ':''}${i===si?'current ':''}${i>si?'blocked':''}">${i<si?'✓ ':''}${x[1]}<small>${i===si?'الحالة الحالية':i<si?'تم':'لاحقًا'}</small></div>`).join('');const cockpit=`<div class="order-cockpit"><div class="stepper">${stepper}</div><div class="next-action"><div><b>الإجراء التالي: ${nextActionText(o)}</b><br><span>مدة الطلب: ${elapsedText(o.created_at)} · ${o.customer_confirmed?'العميل أكد السعر':'تأكيد العميل مطلوب'}</span></div><span class="smart-badge ${urgencyClass(o)}">${urgencyClass(o)==='urgent'?'⚠️ يحتاج تدخل سريع':'● متابعة'}</span></div></div>`;document.getElementById('modalBody').innerHTML=`${cockpit}<div class="detail-grid"><div class="detail"><small>👤 العميل</small><b>${esc(o.customer_name)}</b></div><div class="detail"><small>📞 الهاتف</small><b>${esc(o.phone)}</b></div><div class="detail"><small>📍 العنوان</small><b>${esc(o.address)}</b></div><div class="detail"><small>🏬 الفرع</small><b>${esc(o.branch_id||window.sgBranchName||'')}</b></div><div class="detail"><small>💳 الدفع</small><b>${payName(o.payment)}</b></div><div class="detail"><small>🕒 وقت الطلب</small><b>${esc(o.created_at)}</b></div></div><div style="margin-top:14px;padding:12px 14px;border:1px solid #24485d;border-radius:14px;background:#071923;display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap"><b style="font-size:15px">📦 مراجعة الأصناف والوزن</b><span style="color:#9eb2c1;font-size:11px">اكتب الوزن بالكيلو: 0.750 = 750 جم</span></div><table class="items"><thead><tr><th>الصنف</th><th>الكمية المطلوبة</th><th>الكمية بعد المراجعة</th><th>الوزن المطلوب</th><th>الوزن بعد المراجعة (كجم)</th><th>سعر الوحدة</th><th>إجمالي الصنف</th></tr></thead><tbody>${items.map(i=>{const rw=parseRequestedWeight(i),aw=(i.actual_weight!==null&&i.actual_weight!==undefined&&i.actual_weight!=='')?Number(i.actual_weight):rw;const rq=Number(i.qty||0),aq=(i.actual_qty!==null&&i.actual_qty!==undefined&&i.actual_qty!=='')?Number(i.actual_qty):rq;return `<tr><td><b>${esc(i.item_name)}</b>${i.method_name?`<div class="muted" style="color:#6be5aa">🍳 ${esc(i.method_name)}${Number(i.method_price||0)>0?' (+'+money(i.method_price)+')':''}</div>`:''}${i.note?`<div class="muted">${esc(i.note)}</div>`:''}</td><td>${rq||'-'}</td><td><input id="aq_${i.id}" type="number" min="0" step="1" value="${aq||0}" style="width:78px" class="search"></td><td>${fmtGrams(rw)}</td><td><input id="aw_${i.id}" type="number" min="0.150" step="0.050" inputmode="decimal" value="${aw!==null&&aw!==undefined&&aw!==''?(Number(aw)/1000).toFixed(3):''}" placeholder="0.750" style="width:105px" class="search"><div class="muted">0.750 = 750 جم</div></td><td>${money(i.unit_price)}${rw?' / كجم':''}</td><td>${money(i.actual_line_total??i.line_total)}</td></tr>`}).join('')}</tbody></table><div class="detail" style="margin-top:12px"><small>خدمة التوصيل</small><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:7px"><input id="deliveryFeeInput" type="number" min="0" step="0.25" value="${Number(o.delivery_fee||0).toFixed(2)}" style="background:#071521;border:1px solid #1e3b50;color:#fff;border-radius:9px;padding:9px;width:140px"><span>ج.م</span><button class="btn" onclick="adjustDelivery(${o.id},10)">➕ 10</button><button class="btn" onclick="adjustDelivery(${o.id},-10)">➖ 10</button><button class="btn" onclick="resetDeliveryAuto(${o.id})">📍 تلقائي</button><button class="btn primary" onclick="updateOrderItems(${o.id})">🔄 حفظ الوزن</button></div></div><div class="detail-grid" style="margin-top:12px"><div class="detail"><small>إجمالي الأصناف</small><b>${money(o.subtotal)}</b></div><div class="detail"><small>ضريبة 14%</small><b>${money(o.tax_amount||0)}</b></div><div class="detail"><small>خدمة التوصيل</small><b>${money(o.delivery_fee||0)}</b></div><div class="detail"><small>خصم 10%</small><b>− ${money(o.discount||0)}</b></div><div class="detail" style="border:2px solid #2d8b68"><small>الإجمالي النهائي بعد المراجعة</small><b style="color:#6be5aa;font-size:21px">${money(o.total)}</b></div></div><div class="detail" style="margin-top:12px;border:1px solid #4b6b80"><small>حالة السعر وتأكيد العميل</small><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:7px"><span style="color:${o.price_pending?'#ffd05c':'#62e8a9'}">${o.price_pending?'🟡 السعر يحتاج اعتماد':'🟢 السعر معتمد'}</span><span style="color:${o.customer_confirmed?'#62e8a9':'#ffd05c'}">${o.customer_confirmed?'✅ العميل وافق':'⏳ في انتظار موافقة العميل'}</span><input id="finalPriceInput" type="number" min="0" step="0.25" value="${Number(o.total||0).toFixed(2)}" style="background:#071521;border:1px solid #1e3b50;color:#fff;border-radius:9px;padding:9px;width:150px"><button class="btn green" onclick="confirmFinalPrice(${o.id})">✅ اعتماد السعر</button><button class="btn" onclick="sendFinalWhatsApp(${o.id})">📩 إشعار نصي بالسعر</button><button class="btn green" ${o.price_pending?'disabled title="اعتمد السعر النهائي أولًا"':''} onclick="${o.price_pending?'toast(\"اعتمد السعر النهائي أولًا ثم أرسل الشيك\")':'shareFinalReceipt('+o.id+')'}">📷 إرسال صورة الشيك للعميل</button></div></div><div class="modal-actions"><button class="btn primary" onclick="printOrder(${o.id})">🖨 طباعة الشيك 80mm</button>${o.location_url?`<button class="btn green" onclick="openLocation(${o.id})">📍 فتح الخريطة</button><button class="btn" onclick="driverWhatsApp(${o.id})">🚚 واتساب للدليفري</button>`:''}<button class="btn" onclick="loadOrderHistory(${o.id})">🕘 سجل الطلب</button><button class="btn" onclick="nextStatus(${o.id});closeModal()">→ الحالة التالية</button><button class="btn" onclick="closeModal()">إغلاق</button></div>`;document.getElementById('modal').classList.add('open')}
async function adjustDelivery(id,delta){const o=orders.find(x=>x.id==id);if(!o)return;const fee=Math.max(0,Math.round((Number(o.delivery_fee||0)+Number(delta))*100)/100);const r=await fetch('api.php?action=set_delivery_fee&key='+encodeURIComponent(key),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,mode:'manual',fee})});const d=await r.json();if(!d.ok)return toast(d.error||'تعذر تعديل التوصيل');await loadOrders();viewOrder(id);toast((delta>0?'➕ ':'➖ ')+'تم تعديل التوصيل إلى '+money(d.fee)+' ج.م — ويحتاج موافقة العميل من جديد');}
async function resetDeliveryAuto(id){const r=await fetch('api.php?action=set_delivery_fee&key='+encodeURIComponent(key),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,mode:'auto'})});const d=await r.json();if(!d.ok)return toast(d.error||'تعذر إعادة الحساب');await loadOrders();viewOrder(id);toast('📍 تم إرجاع التوصيل للحساب التلقائي');}
async function updateOrderItems(id){const o=orders.find(x=>x.id==id);if(!o)return;const items=(o.items||[]).map(i=>{const raw=document.getElementById('aw_'+i.id)?.value||'';const kg=raw===''?'':Number(String(raw).replace(',','.'));return {id:i.id,qty:Number(document.getElementById('aq_'+i.id)?.value||0),actual_weight:raw===''?'':Math.round(kg*1000)};});const delivery=Number(document.getElementById('deliveryFeeInput')?.value||0);const r=await fetch('api.php?action=update_order_items&key='+encodeURIComponent(key),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,items,delivery_fee:delivery})});const d=await r.json();if(!d.ok)return toast(d.error||'تعذر إعادة الحساب');await loadOrders();viewOrder(id);toast('✅ تم حفظ الأوزان وإعادة حساب الشيك')}
function sendFinalWhatsApp(id){const o=orders.find(x=>x.id==id);if(!o)return;let phone=String(o.phone||'').replace(/\D/g,'');if(!phone)return toast('رقم العميل غير موجود');const intl=phone.startsWith('0')?'20'+phone.slice(1):phone;const lines=['🦀 Sea Gull — تأكيد السعر النهائي','طلب #'+o.order_no,''];(o.items||[]).forEach(i=>{const aw=(i.actual_weight!==null&&i.actual_weight!==undefined&&i.actual_weight!=='')?fmtGrams(i.actual_weight):fmtGrams(parseRequestedWeight(i));lines.push('• '+i.item_name+(i.method_name?' ('+i.method_name+')':'')+' | كمية '+(i.actual_qty||i.qty||1)+(aw!=='-'?' | وزن '+aw:'')+' | '+money(i.actual_line_total??i.line_total));});lines.push('','إجمالي الأصناف: '+money(o.subtotal),'ضريبة 14%: '+money(o.tax_amount||0),'خدمة التوصيل: '+money(o.delivery_fee||0),'خصم 10%: -'+money(o.discount||0),'','💰 الإجمالي النهائي: '+money(o.total)+' ج.م','','✅ بعد مراجعة السعر اضغط رابط التتبع لتأكيد الطلب: '+new URL('index.php', window.location.href).href+'?track='+encodeURIComponent(o.order_no)+'&phone='+encodeURIComponent(o.phone));window.open('https://wa.me/'+intl+'?text='+encodeURIComponent(lines.join('\n')),'_blank','noopener')}
async function shareFinalReceipt(id){
  const o=orders.find(x=>x.id==id); if(!o)return;
  if(Number(o.price_pending)){ toast('اعتمد السعر النهائي وراجع الأوزان أولاً'); return; }
  const items=o.items||[];
  const rows=items.map(i=>{
    const weightMode=isWeightItem(i), menuItem=(window.MENU_DATA?.items||[]).find(m=>String(m.id)===String(i.item_id));
    const shrimp=weightMode && menuItem?.cat==='shrimp';
    const aw=weightMode&&i.actual_weight!==null&&i.actual_weight!==undefined&&i.actual_weight!==''?Number(i.actual_weight):null;
    const detail=weightMode?`<div style="font-size:9px;color:#555">فعلي: ${fmtGrams(aw||0)}</div>`:'';
    const qty=shrimp?'—':(i.actual_qty||i.qty||'-');
    return `<tr><td><b>${esc(i.item_name)}</b>${detail}${i.note?`<div style="font-size:9px;color:#555">ملاحظة: ${esc(i.note)}</div>`:''}</td><td style="text-align:center">${qty}</td><td style="text-align:left;font-weight:900">${money(i.actual_line_total??i.line_total)}</td></tr>`;
  }).join('');
  const wrap=document.createElement('div');
  wrap.style.cssText='position:fixed;left:-10000px;top:0;width:302px;background:#fff;color:#111;padding:22px 16px;font-family:Tahoma,Arial,sans-serif;font-size:12px;direction:rtl;box-sizing:border-box';
  wrap.innerHTML=`<div style="text-align:center"><img src="${logoData()}" style="width:180px;max-height:75px;object-fit:contain"><h2 style="margin:4px 0">Sea Gull Restaurant</h2><div>طلب #${esc(o.order_no)}</div><div style="font-weight:900;margin-top:4px">أوردر رقم: #${esc(o.daily_serial||'—')}</div><div style="font-size:9px;color:#666">${esc(o.created_at||'')}</div></div>
  <div style="border-top:1px dashed #555;margin:10px 0"></div>
  <div><b>العميل:</b> ${esc(o.customer_name)}<br><b>موبايل:</b> ${esc(o.phone)}<br><b>الفرع:</b> ${esc(o.branch_id||window.sgBranchName||'')}</div>
  <div style="border-top:1px dashed #555;margin:10px 0"></div>
  <table style="width:100%;border-collapse:collapse"><thead><tr><th style="text-align:right;padding:5px 0;border-bottom:1px dotted #aaa">الصنف</th><th style="padding:5px 0;border-bottom:1px dotted #aaa">كم</th><th style="text-align:left;padding:5px 0;border-bottom:1px dotted #aaa">السعر</th></tr></thead><tbody>${rows}</tbody></table>
  <div style="border-top:1px dashed #555;margin:10px 0"></div>
  <div style="display:flex;justify-content:space-between;margin:4px 0"><span>إجمالي الأصناف</span><b>${money(o.subtotal)}</b></div>
  <div style="display:flex;justify-content:space-between;margin:4px 0"><span>ضريبة 14%</span><b>+ ${money(o.tax_amount||0)}</b></div>
  <div style="display:flex;justify-content:space-between;margin:4px 0"><span>خدمة التوصيل</span><b>+ ${money(o.delivery_fee||0)}</b></div>
  <div style="display:flex;justify-content:space-between;margin:4px 0"><span>الخصم</span><b>− ${money(o.discount||0)}</b></div>
  <div style="border-top:1px dashed #555;margin:10px 0"></div>
  <div style="display:flex;justify-content:space-between;font-size:17px;font-weight:900"><span>الإجمالي النهائي</span><span>${money(o.total)} ج.م</span></div>
  <div style="text-align:center;font-size:9px;color:#555;margin-top:12px">السعر النهائي بعد مراجعة الوزن<br>شكرًا لاختيار Sea Gull ❤️</div>${o.location_url?`<div style="text-align:center;margin-top:10px"><img src="https://quickchart.io/qr?size=180&text=${encodeURIComponent(o.location_url)}" style="width:150px;height:150px;object-fit:contain"><div style="font-size:8px">امسح QR لفتح موقع العميل</div></div>`:''}`;
  document.body.appendChild(wrap);
  try{
    if(typeof html2canvas!=='function') throw new Error('canvas');
    const canvas=await html2canvas(wrap,{backgroundColor:'#fff',scale:2,useCORS:true});
    const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));
    const file=new File([blob],`SeaGull-${o.order_no}-receipt.png`,{type:'image/png'});
    const itemLines=items.map(i=>{const rw=parseRequestedWeight(i);const aw=(i.actual_weight!==null&&i.actual_weight!==undefined&&i.actual_weight!=='')?Number(i.actual_weight):rw;const qty=i.actual_qty||i.qty||0;const line=money(i.actual_line_total??i.line_total);return `• ${i.item_name} — ${qty}${rw?` — ${fmtGrams(aw)}`:''} — ${line} ج.م`;}).join('\n');
    const text=[
      `🧾 *Sea Gull — الشيك النهائي*`,
      `رقم الطلب: #${o.order_no}`,
      `العميل: ${o.customer_name}`,
      `الفرع: ${o.branch_id||window.sgBranchName||''}`,
      '',
      `*الأصناف:*`, itemLines,
      '',
      `إجمالي الأصناف: ${money(o.subtotal)} ج.م`,
      `الضريبة 14%: ${money(o.tax_amount||0)} ج.م`,
      `التوصيل: ${money(o.delivery_fee||0)} ج.م`,
      `الخصم: ${money(o.discount||0)} ج.م`,
      `💰 *الإجمالي النهائي: ${money(o.total)} ج.م*`,
      '',
      `بعد مراجعة الأوزان والسعر، اضغط الرابط لتأكيد الطلب:`,
      `${location.origin}/index.php?track=${encodeURIComponent(o.order_no)}&phone=${encodeURIComponent(o.phone)}`
    ].filter(v=>v!==null&&v!==undefined).join('\n');
    if(navigator.canShare && navigator.canShare({files:[file]})){
      const intl=String(o.phone||'').replace(/\D/g,'');const wa=intl?(intl.startsWith('0')?'20'+intl.slice(1):intl):'';if(wa){try{window.open('https://wa.me/'+wa,'_blank','noopener');}catch(e){}}await navigator.share({title:`Sea Gull — طلب #${o.order_no}`,text,files:[file]});
      toast('📲 فتحنا محادثة العميل — اختر WhatsApp من المشاركة لإرسال صورة الشيك');
    }else{
      const intl=String(o.phone||'').replace(/\D/g,'');const wa=intl?(intl.startsWith('0')?'20'+intl.slice(1):intl):'';
      const dlUrl=URL.createObjectURL(blob);const a=document.createElement('a');a.href=dlUrl;a.download=file.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(dlUrl),15000);
      const shortNote=`🧾 Sea Gull — شيك طلب #${o.order_no}\nصورة الشيك اتنزلت على الجهاز — أرفقها هنا مع رسالتك للعميل.`;
      if(wa)window.open('https://wa.me/'+wa+'?text='+encodeURIComponent(shortNote),'_blank','noopener');
      toast('📷 اتنزلت صورة الشيك على جهازك — أرفقها في محادثة الواتساب اللي اتفتحت للعميل');
    }
  }catch(e){console.error(e);toast('تعذر تجهيز صورة الشيك على هذا الجهاز');}
  finally{wrap.remove();}
}
function openLocation(id){const o=orders.find(x=>x.id==id);if(o?.location_url)window.open(o.location_url,'_blank','noopener');}
function driverWhatsApp(id){const o=orders.find(x=>x.id==id);if(!o)return;if(!o.location_url){toast('الطلب لا يحتوي على لوكيشن من العميل');return}let phone=(settings.driver_whatsapp||'').replace(/\D/g,'');if(!phone){phone=prompt('اكتب رقم WhatsApp الدليفري مرة واحدة:','');if(phone){settings.driver_whatsapp=phone.replace(/\D/g,'');saveSettings();}else return}const intl=phone.startsWith('0')?'20'+phone.slice(1):phone;const msg=['🚚 Sea Gull — طلب #'+o.order_no,'العميل: '+o.customer_name,'موبايل: '+o.phone,'العنوان: '+o.address,'الدفع: '+payName(o.payment),'الإجمالي: '+money(o.total),'📍 موقع الاستلام:',o.location_url,settings.delivery_note||''].filter(Boolean).join('\n');window.open('https://wa.me/'+intl+'?text='+encodeURIComponent(msg),'_blank','noopener');}
async function loadOrderHistory(id){try{const r=await fetch('api.php?action=order_history&id='+encodeURIComponent(id),{credentials:'include'});const d=await r.json();if(!d.ok)return toast(d.error||'تعذر تحميل سجل الطلب');document.getElementById('modalTitle').textContent='🕘 سجل الطلب #'+(orders.find(x=>x.id==id)?.order_no||id);document.getElementById('modalBody').innerHTML=`<div class="queue">${d.logs.map(x=>`<div class="q"><div class="qtop"><b>${esc(x.action||'')}</b><span>${esc(x.created_at||'')}</span></div><div style="margin-top:6px">${esc(x.details||'')}</div></div>`).join('')||'<div style="padding:20px">لا يوجد سجل بعد</div>'}</div><div class="modal-actions"><button class="btn" onclick="viewOrder(${id})">↩ العودة للطلب</button></div>`;}catch(e){toast('تعذر الاتصال بالسيرفر')}}
function closeModal(){document.getElementById('modal').classList.remove('open');currentOrderId=null}
async function confirmFinalPrice(id){const el=document.getElementById('finalPriceInput');const finalPrice=Number(el?.value);if(!Number.isFinite(finalPrice)||finalPrice<0){toast('اكتب السعر النهائي الصحيح');return;}if(!confirm('تأكيد السعر النهائي '+money(finalPrice)+' ج.م لهذا الطلب؟'))return;const r=await fetch('api.php?action=confirm_price&key='+encodeURIComponent(key),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,final_price:finalPrice})});const d=await r.json();if(d.ok){const o=orders.find(x=>x.id==id);if(o){o.total=finalPrice;o.price_pending=0;}closeModal();await loadOrders();toast('✅ تم تأكيد السعر النهائي');}else toast(d.error||'تعذر تأكيد السعر');}
async function nextStatus(id){const o=orders.find(x=>x.id==id);if(!o)return;if(o.status==='cancelled'||o.status==='delivered')return;if(o.status==='accepted'&&!Number(o.customer_confirmed)){toast('⏳ لا يمكن بدء التجهيز قبل موافقة العميل على السعر النهائي');viewOrder(id);return}const seq=['new','accepted','preparing','ready','out_for_delivery','delivered'];let i=seq.indexOf(o.status);let st=seq[Math.min(i+1,seq.length-1)];if(i<0)st='accepted';await updateStatus(id,st)}
async function updateStatus(id,status){const r=await fetch('api.php?action=update_status&key='+encodeURIComponent(key),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,status})});const d=await r.json();if(d.ok){stopAlarm();await loadOrders();toast('تم تحديث حالة الطلب')}}
function logoData(){return 'data:image/png;base64,';}
function printOrder(id,auto=false){const o=orders.find(x=>x.id==id);if(!o)return;const items=o.items||[];const rows=items.map(i=>{const rw=parseRequestedWeight(i);const aw=(i.actual_weight!==null&&i.actual_weight!==undefined&&i.actual_weight!=='')?Number(i.actual_weight):rw;return `<tr><td><b>${esc(i.item_name)}</b><br><small>${i.method_name?'🍳 '+esc(i.method_name)+(Number(i.method_price||0)>0?' (+'+money(i.method_price)+')':'')+'<br>':''}${rw?'مطلوب: '+fmtGrams(rw)+' | فعلي: '+fmtGrams(aw):''}${i.note?'<br>ملاحظة: '+esc(i.note):''}</small></td><td>${i.actual_qty||i.qty||'-'}</td><td>${money(i.actual_line_total??i.line_total)}</td></tr>`}).join('');
 const html=`<!doctype html><html dir="rtl"><head><meta charset="utf-8"><title>${esc(o.order_no)}</title><style>@page{size:80mm auto;margin:0}*{box-sizing:border-box}body{width:80mm;margin:0;padding:6mm 4mm;font-family:Tahoma,Arial,sans-serif;color:#111;font-size:11px}.logo{width:48mm;max-height:20mm;object-fit:contain;margin:0 auto 4mm;display:block}.center{text-align:center}.line{border-top:1px dashed #555;margin:3mm 0}table{width:100%;border-collapse:collapse}th,td{padding:2mm 0;border-bottom:1px dotted #aaa;text-align:right;vertical-align:top}th{font-size:9px}td:nth-child(2){width:10mm;text-align:center}td:nth-child(3){width:21mm;text-align:left;font-weight:bold}.sum{display:flex;justify-content:space-between;margin:1.5mm 0}.total{font-size:17px;font-weight:900}.small{font-size:9px}</style></head><body><img class="logo" src="${logoData()}"><div class="center"><h2 style="margin:0">Sea Gull Restaurant</h2><div>طلب #${esc(o.order_no)}</div><div style="font-weight:900;margin-top:2mm">أوردر رقم: #${esc(o.daily_serial||'—')}</div><div class="small">${esc(o.created_at)}</div></div><div class="line"></div><div><b>العميل:</b> ${esc(o.customer_name)}<br><b>موبايل:</b> ${esc(o.phone)}<br><b>الفرع:</b> ${esc(o.branch_id||window.sgBranchName||'')}</div><div class="line"></div><table><thead><tr><th>الصنف / الوزن</th><th>كم</th><th>السعر</th></tr></thead><tbody>${rows}</tbody></table><div class="line"></div><div class="sum"><span>إجمالي الأصناف</span><b>${money(o.subtotal)}</b></div><div class="sum"><span>ضريبة 14%</span><b>+ ${money(o.tax_amount||0)}</b></div><div class="sum"><span>خدمة التوصيل</span><b>+ ${money(o.delivery_fee||0)}</b></div><div class="sum"><span>خصم 10%</span><b>− ${money(o.discount||0)}</b></div><div class="line"></div><div class="sum total"><span>الإجمالي النهائي</span><span>${money(o.total)} ج.م</span></div><div class="center small" style="margin-top:4mm">السعر النهائي بعد مراجعة الوزن</div>${o.note?`<div class="line"></div><b>ملاحظات:</b> ${esc(o.note)}`:''}${o.location_url?`<div class="line"></div><div class="center"><div class="small">📍 موقع العميل</div><img src="https://quickchart.io/qr?size=180&text=${encodeURIComponent(o.location_url)}" style="width:34mm;height:34mm;object-fit:contain;margin-top:2mm"><div class="small">امسح QR لفتح الموقع</div></div>`:''}</body></html>`;
 if(auto){
   let f=document.getElementById('sgAutoPrintFrame');
   if(!f){f=document.createElement('iframe');f.id='sgAutoPrintFrame';f.style.cssText='position:fixed;width:0;height:0;border:0;visibility:hidden';document.body.appendChild(f);}
   const doc=f.contentWindow.document;doc.open();doc.write(html);doc.close();
   const doPrint=()=>{try{f.contentWindow.focus();f.contentWindow.print();}catch(e){console.warn('auto print failed',e);}};
   if(f.contentDocument&&f.contentDocument.readyState==='complete')setTimeout(doPrint,60);else f.onload=()=>setTimeout(doPrint,60);
   return true;
 }
 const w=(printWindow&&!printWindow.closed)?printWindow:window.open('','_blank','width=380,height=720');if(!w){toast('المتصفح منع نافذة الطباعة؛ اسمح بالنوافذ المنبثقة لهذا الموقع ثم جرب تاني');return false}
 const printBar=`<div class="no-print" style="position:sticky;top:0;background:#0c2333;padding:10px;display:flex;gap:8px;justify-content:center;z-index:9"><button onclick="window.print()" style="background:#2d8b68;color:#fff;border:0;border-radius:8px;padding:10px 18px;font-size:14px;font-weight:900;cursor:pointer">🖨 اطبع الآن</button><button onclick="window.close()" style="background:#5b6b78;color:#fff;border:0;border-radius:8px;padding:10px 18px;font-size:14px;cursor:pointer">إغلاق</button></div>`;
 const printCss=`<style>@media print{.no-print{display:none!important}}</style>`;
 w.document.write(html.replace('</head>',printCss+'</head>').replace('<body>','<body>'+printBar).replace('</body></html>','<script>window.onload=()=>{setTimeout(()=>{try{window.print()}catch(e){}},250)}<\\/script></body></html>'));w.document.close();return true}function methodRowHtml(m){const id=m.id||('new'+Math.random().toString(36).slice(2,8));return `<div class="method-row" data-mid="${esc(id)}" style="display:flex;gap:8px;align-items:center;margin-bottom:6px"><input class="m-ar" placeholder="اسم طريقة التحضير (مثال: بطاطس كريمة)" value="${esc(m.ar||'')}" style="flex:2"><input class="m-en" placeholder="English name" value="${esc(m.en||'')}" style="flex:2"><input class="m-price" type="number" min="0" step="0.5" placeholder="سعر إضافي" value="${m.extra_price??0}" style="width:100px"><button class="mini" onclick="this.closest('.method-row').remove()">🗑</button></div>`}
function addMethodRow(){const box=document.getElementById('methodsBox');if(box)box.insertAdjacentHTML('beforeend',methodRowHtml({}))}
function collectMethods(){return [...document.querySelectorAll('#methodsBox .method-row')].map(row=>({id:row.dataset.mid?.startsWith('new')?'':row.dataset.mid,ar:row.querySelector('.m-ar').value.trim(),en:row.querySelector('.m-en').value.trim(),extra_price:Number(row.querySelector('.m-price').value||0)})).filter(m=>m.ar)}
function openItem(it=null){const cats=Object.entries(menu.cats).map(([id,n])=>`<option value="${id}" ${it?.cat===id?'selected':''}>${esc(n[0])}</option>`).join('');document.getElementById('modalTitle').textContent=it?'تعديل صنف':'إضافة صنف';document.getElementById('modalBody').innerHTML=`<div class="form-grid"><div class="field"><label>الاسم عربي</label><input id="iAr" value="${esc(it?.ar||'')}"></div><div class="field"><label>الاسم English</label><input id="iEn" value="${esc(it?.en||'')}"></div><div class="field"><label>السعر</label><input id="iPrice" type="number" value="${it?.price||0}"></div><div class="field"><label>القسم</label><select id="iCat">${cats}</select></div><div class="field"><label>طريقة التسعير</label><div style="padding:10px;border:1px solid #1e3b50;border-radius:9px;background:#071521;color:#dce8f0">${['fish','shrimp'].includes(it?.cat)?'⚖️ بالوزن — تلقائي للسمك والجمبري':'🔢 بالعدد — تلقائي لباقي الأصناف'}</div></div><div class="field"><label>الوصف عربي</label><textarea id="iDar">${esc(it?.dar||'')}</textarea></div><div class="field"><label>الوصف English</label><textarea id="iDen">${esc(it?.den||'')}</textarea></div><div class="field"><label>الوزن/العدد الظاهر للعميل (مثال: 300 جم — يكفي فردًا واحدًا)</label><input id="iServing" value="${esc(it?.serving_info||'')}"></div><div class="field"><label>المكونات الظاهرة للعميل (مثال: جمبري، كريمة، ثوم)</label><input id="iIngText" value="${esc(it?.ingredients_text||'')}"></div></div>${it?'<div style="padding:0 16px 16px"><button class="btn" onclick="fillIngredientsFromRecipe(\''+esc(it.id)+'\')">🔄 تعبئة المكونات تلقائيًا من الوصفة</button></div>':''}<div style="padding:0 16px 16px"><div style="border:1px solid #1e3b50;border-radius:12px;padding:12px;background:#061a26"><b style="display:block;margin-bottom:8px">🍳 طرق التحضير/التسوية (اختياري — لكل طريقة سعر إضافي خاص بيها)</b><div id="methodsBox">${(it?.methods||[]).map(methodRowHtml).join('')}</div><button class="btn" onclick="addMethodRow()">➕ إضافة طريقة تحضير</button></div></div><div style="padding:0 16px 16px"><div style="border:1px solid #1e3b50;border-radius:12px;padding:12px;background:#061a26"><b style="display:block;margin-bottom:8px">🧾 وصفة الصنف (لخصم المخزون تلقائيًا عند البيع)</b><div id="recipeBox">${it?'<div class="muted">جاري تحميل الوصفة…</div>':'<div class="muted">احفظ الصنف أولًا لإضافة وصفة له.</div>'}</div>${it?'<button class="btn" onclick="addRecipeRow(\''+esc(it.id)+'\')">➕ إضافة مكوّن للوصفة</button> <button class="btn primary" onclick="saveRecipeRows(\''+esc(it.id)+'\')">💾 حفظ الوصفة</button>':''}</div></div><div style="padding:0 16px 16px"><button class="btn primary" onclick="saveItem('${esc(it?.id||'')}')">💾 حفظ</button> ${it?`<button class="btn red" onclick="deleteItem('${esc(it.id)}')">حذف</button>`:''}</div>`;document.getElementById('modal').classList.add('open');if(it)initRecipeEditor(it);}
async function initRecipeEditor(it){ if(!INGREDIENTS_CACHE.length) await loadIngredients(); const r=await fetch('api.php?action=get_item_recipe&item_id='+encodeURIComponent(it.id)+'&key='+encodeURIComponent(key)); const d=await r.json(); const rows=d.ok?(d.recipe||[]):[]; const box=document.getElementById('recipeBox'); if(!box)return; box.innerHTML=rows.length?rows.map(rr=>recipeRowHtml(it,rr)).join(''):''; }
function recipeRowHtml(it,rr={}){const rid='r'+Math.random().toString(36).slice(2,8);const methods=it.methods||[];const ingOptions=INGREDIENTS_CACHE.map(i=>`<option value="${i.id}" ${Number(rr.ingredient_id)===i.id?'selected':''}>${esc(i.name_ar)} (${esc(i.unit)})</option>`).join('');const methodOptions=`<option value="" ${!rr.method_id?'selected':''}>أساسي (كل الطرق)</option>`+methods.map(m=>`<option value="${m.id}" ${rr.method_id===m.id?'selected':''}>${esc(m.ar)}</option>`).join('');return `<div class="method-row" data-rid="${rid}" style="display:flex;gap:8px;align-items:center;margin-bottom:6px"><select class="r-ing" style="flex:2">${ingOptions}</select><select class="r-method" style="flex:1">${methodOptions}</select><input class="r-qty" type="number" min="0" step="0.01" placeholder="الكمية لكل وحدة بيع" value="${rr.qty_per_unit??''}" style="width:120px"><button class="mini" onclick="this.closest('.method-row').remove()">🗑</button></div>`}
function addRecipeRow(itemId){const it=menu.items.find(x=>x.id===itemId);const box=document.getElementById('recipeBox');if(!box)return;if(!INGREDIENTS_CACHE.length){toast('أضف مكونات خام أولًا من صفحة المخزون');return}box.insertAdjacentHTML('beforeend',recipeRowHtml(it,{}))}
async function saveRecipeRows(itemId){const rows=[...document.querySelectorAll('#recipeBox .method-row')].map(row=>({ingredient_id:Number(row.querySelector('.r-ing').value),method_id:row.querySelector('.r-method').value,qty_per_unit:Number(row.querySelector('.r-qty').value||0)})).filter(r=>r.ingredient_id&&r.qty_per_unit>0);const r=await fetch('api.php?action=save_item_recipe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({item_id:itemId,rows})});const d=await r.json();if(d.ok)toast('تم حفظ الوصفة');else toast(d.error||'خطأ')}
async function saveItem(id){const b={id,ar:document.getElementById('iAr').value,en:document.getElementById('iEn').value,price:Number(document.getElementById('iPrice').value),cat:document.getElementById('iCat').value,pricing_mode:(['fish','shrimp'].includes(document.getElementById('iCat').value)?'weight':'qty'),dar:document.getElementById('iDar').value,den:document.getElementById('iDen').value,serving_info:document.getElementById('iServing').value,ingredients_text:document.getElementById('iIngText').value,methods:collectMethods()};const r=await fetch('api.php?action=save_item&key='+encodeURIComponent(key),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});const d=await r.json();if(d.ok){menu=d.menu;closeModal();renderProducts();toast('تم حفظ الصنف') }else toast('تعذر حفظ الصنف')}
async function fillIngredientsFromRecipe(itemId){const r=await fetch('api.php?action=get_item_recipe&item_id='+encodeURIComponent(itemId)+'&key='+encodeURIComponent(key));const d=await r.json();if(!d.ok||!d.recipe||!d.recipe.length){toast('لا توجد وصفة محفوظة لهذا الصنف بعد');return}const names=[...new Set(d.recipe.map(r=>r.name_ar))];document.getElementById('iIngText').value=names.join('، ');toast('تم التعبئة — لا تنسَ حفظ الصنف')}
async function deleteItem(id){if(!confirm('حذف الصنف؟'))return;const r=await fetch('api.php?action=delete_item&key='+encodeURIComponent(key),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});const d=await r.json();if(d.ok){menu=d.menu;closeModal();renderProducts();toast('تم حذف الصنف')}}
function openCat(){document.getElementById('modalTitle').textContent='إضافة قسم';document.getElementById('modalBody').innerHTML='<div class="form-grid"><div class="field"><label>معرّف القسم بالإنجليزية</label><input id="cId" placeholder="grills"></div><div class="field"><label>اسم القسم عربي</label><input id="cAr"></div><div class="field"><label>اسم القسم English</label><input id="cEn"></div><div class="field"><label>الأيقونة</label><input id="cIcon" value="🍽️"></div></div><div style="padding:0 16px 16px"><button class="btn primary" onclick="saveCat()">حفظ القسم</button></div>';document.getElementById('modal').classList.add('open')}
async function saveCat(){const b={id:document.getElementById('cId').value,ar:document.getElementById('cAr').value,en:document.getElementById('cEn').value,icon:document.getElementById('cIcon').value};const r=await fetch('api.php?action=save_category&key='+encodeURIComponent(key),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});const d=await r.json();if(d.ok){menu=d.menu;closeModal();renderProducts();toast('تم إضافة القسم')}}
let OPEN_CATS=new Set();
function toggleCatOpen(catId){if(OPEN_CATS.has(catId))OPEN_CATS.delete(catId);else OPEN_CATS.add(catId);renderProducts()}
function renderProducts(){
  const q=(document.getElementById('productSearch')?.value||'').toLowerCase();
  const groups={}; const order=[];
  Object.keys(menu.cats).forEach(cid=>{groups[cid]=[];order.push(cid)});
  menu.items.forEach(it=>{if(!groups[it.cat])(groups[it.cat]=[],order.push(it.cat));groups[it.cat].push(it)});
  const forceOpenAll=!!q;
  document.getElementById('productsGrid').innerHTML=order.map(cid=>{
    const items=groups[cid].filter(x=>!q||[x.ar,x.en].join(' ').toLowerCase().includes(q));
    if(q && !items.length) return '';
    const isOpen=forceOpenAll||OPEN_CATS.has(cid);
    const catName=menu.cats[cid]?.[0]||cid;
    return `<div class="cat-accordion" style="border:1px solid #1e3b50;border-radius:12px;margin-bottom:10px;overflow:hidden">
      <div onclick="toggleCatOpen('${cid}')" style="cursor:pointer;display:flex;justify-content:space-between;align-items:center;padding:14px 16px;background:#0c2333">
        <b>${esc(catName)} <span class="muted">(${items.length})</span></b>
        <span>${isOpen?'▲':'▼'}</span>
      </div>
      ${isOpen?`<div class="products" style="padding:12px">${items.map(it=>`<div class="product"><div class="phead"><b>${esc(it.ar)}</b><button class="mini" onclick='event.stopPropagation();openItem(${JSON.stringify(it).replace(/'/g,"&#39;")})'>✏️</button></div><small>${esc(it.en)}${it.methods&&it.methods.length?' • 🍳 '+it.methods.length+' طريقة تحضير':''}${it.available===false?' • 🔴 غير متاح':''}</small><div class="price">${money(it.price)}</div></div>`).join('')||'<div class="muted" style="padding:10px">لا توجد أصناف في هذا القسم</div>'}</div>`:''}
    </div>`;
  }).join('');
}
let CUSTOMERS_CACHE=[];
async function loadCustomers(){const r=await fetch('api.php?action=customers&key='+encodeURIComponent(key));const d=await r.json();if(!d.ok)return;CUSTOMERS_CACHE=d.customers||[];renderCustomersFiltered()}
function renderCustomersFiltered(){const q=(document.getElementById('custSearch')?.value||'').trim().toLowerCase();const day=document.getElementById('custDay')?.value||'';const list=CUSTOMERS_CACHE.filter(x=>{const okQ=!q||String(x.customer_name||'').toLowerCase().includes(q)||String(x.phone||'').includes(q);const okDay=!day||String(x.last_order||'').slice(0,10)===day;return okQ&&okDay});document.getElementById('customerRows').innerHTML=list.map(x=>`<tr><td><b>${esc(x.customer_name)}</b></td><td>${esc(x.phone)}</td><td>${esc(x.address)}</td><td>${x.orders_count}</td><td>${money(x.total_spent)}</td><td>${esc(x.last_order)}</td></tr>`).join('')||'<tr><td colspan="6">لا يوجد عملاء مطابقين</td></tr>'}
function setDates(){const t=new Date().toISOString().slice(0,10);document.getElementById('from').value=document.getElementById('from').value||t;document.getElementById('to').value=document.getElementById('to').value||t}
async function loadReport(){setDates();const f=document.getElementById('from').value,t=document.getElementById('to').value;const r=await fetch(`api.php?action=reports&key=${encodeURIComponent(key)}&from=${f}&to=${t}`);const d=await r.json();if(!d.ok)return;reportData=d;const s=d.summary;document.getElementById('reportSummary').innerHTML=`<div class="card"><h3>عدد الطلبات</h3><div class="big">${s.orders_count}</div></div><div class="card"><h3>المبيعات</h3><div class="big">${money(s.total)}</div></div><div class="card"><h3>الخصومات</h3><div class="big">${money(s.discount)}</div></div>`;document.getElementById('reportStatus').innerHTML=d.statuses.map(x=>`<tr><td>${statusNames[x.status]||x.status}</td><td>${x.count}</td></tr>`).join('');document.getElementById('reportPay').innerHTML=d.payments.map(x=>`<tr><td>${payName(x.payment)}</td><td>${x.count}</td><td>${money(x.total)}</td></tr>`).join('');document.getElementById('reportItems').innerHTML=d.items.map(x=>`<tr><td>${esc(x.item_name)}</td><td>${Number(x.qty||0).toFixed(0)}</td><td>${Number(x.weight||0)?(Number(x.weight)/1000).toFixed(3)+' كجم':'-'}</td><td>${money(x.sales)}</td></tr>`).join('')}
function downloadReportCSV(){if(!reportData){toast('اعرض التقرير أولًا');return}const d=reportData;const rows=[['Sea Gull Report','من','إلى'],['',d.from,d.to],[],['الصنف','الكمية','الوزن','المبيعات'],...d.items.map(x=>[x.item_name,Number(x.qty||0),Number(x.weight||0)?(Number(x.weight)/1000).toFixed(3)+' kg':'',Number(x.sales||0)]),[],['عدد الطلبات',d.summary.orders_count],['المبيعات',d.summary.total],['الخصومات',d.summary.discount]];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`SeaGull_Report_${d.from}_${d.to}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function printReport(){if(!reportData){toast('اعرض التقرير أولًا');return}const d=reportData,w=window.open('','_blank','width=900,height=800');w.document.write(`<html dir="rtl"><head><meta charset="utf-8"><title>تقرير Sea Gull</title><style>body{font-family:Tahoma;padding:25px}table{width:100%;border-collapse:collapse;margin:15px 0}th,td{border:1px solid #aaa;padding:7px;text-align:right}h1{margin-bottom:4px}</style></head><body><h1>Sea Gull Restaurant — تقرير</h1><div>من ${d.from} إلى ${d.to}</div><h3>الملخص</h3><p>عدد الطلبات: ${d.summary.orders_count} | المبيعات: ${money(d.summary.total)} | الخصم: ${money(d.summary.discount)}</p><h3>الأصناف والكميات والأوزان</h3><table><tr><th>الصنف</th><th>الكمية</th><th>الوزن</th><th>المبيعات</th></tr>${d.items.map(x=>`<tr><td>${esc(x.item_name)}</td><td>${Number(x.qty||0).toFixed(0)}</td><td>${Number(x.weight||0)?(Number(x.weight)/1000).toFixed(3)+' كجم':'-'}</td><td>${money(x.sales)}</td></tr>`).join('')}</table><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
async function loadInventory(){const r=await fetch('api.php?action=get_inventory&key='+encodeURIComponent(key));const d=await r.json();if(!d.ok)return;document.getElementById('inventoryRows').innerHTML=d.inventory.map(x=>{const stock=x.stock===null?'':Number(x.stock);const low=x.stock!==null&&Number(x.stock)<=Number(x.reorder_level||0);return `<tr><td><b>${esc(x.name)}</b><div class="muted">${esc(x.name_en)}</div></td><td>${esc(menu.cats[x.cat]?.[0]||x.cat)}</td><td><input id="st_${esc(x.item_id)}" value="${stock}" placeholder="غير محدود" style="width:110px" class="search"></td><td><select id="un_${esc(x.item_id)}" class="select"><option value="pcs" ${x.unit==='pcs'?'selected':''}>قطعة</option><option value="kg" ${x.unit==='kg'?'selected':''}>كجم</option></select></td><td><input id="re_${esc(x.item_id)}" value="${Number(x.reorder_level||0)}" style="width:90px" class="search"></td><td>${x.stock===null?'∞ غير محدود':(low?'⚠️ منخفض':'✅ جيد')}</td><td><button class="mini" onclick="saveInventory('${esc(x.item_id)}')">حفظ</button></td></tr>`}).join('')}
async function saveInventory(id){const stock=document.getElementById('st_'+id).value;const unit=document.getElementById('un_'+id).value;const reorder=document.getElementById('re_'+id).value;const r=await fetch('api.php?action=save_inventory&key='+encodeURIComponent(key),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({item_id:id,stock,unit,reorder_level:reorder})});const d=await r.json();if(d.ok){toast('تم حفظ المخزون');loadInventory()}else toast('تعذر حفظ المخزون')}
async function resetBranchData(branchId,branchName){if(window.sgRole!=='owner')return;if(!confirm('تصفير بيانات '+branchName+' فقط؟\nسيتم حذف طلبات هذا الفرع فقط.'))return;const r=await fetch('api.php?action=reset_branch_data&branch_id='+encodeURIComponent(branchId),{credentials:'include'});const d=await r.json();if(d.ok){toast('تم تصفير '+branchName+' فقط');loadOwner();loadOrders(true)}else toast(d.error||'تعذر التصفير')}
function downloadBackup(){window.location.href='api.php?action=backup&key='+encodeURIComponent(key)}
function toggleAdminLang(){adminLang=adminLang==='ar'?'en':'ar';localStorage.sgAdminLang=adminLang;document.documentElement.lang=adminLang;document.documentElement.dir=adminLang==='en'?'ltr':'rtl';statusNames=adminLang==='en'?{new:'New',accepted:'Accepted',preparing:'Preparing',ready:'Ready',out_for_delivery:'Out for delivery',delivered:'Delivered',cancelled:'Cancelled'}:{new:'جديد',accepted:'مقبول',preparing:'قيد التحضير',ready:'جاهز',out_for_delivery:'خرج للتوصيل',delivered:'تم التسليم',cancelled:'ملغي'};const map=adminLang==='en'?{'لوحة التحكم':'Dashboard','الطلبات':'Orders','الأصناف والأسعار':'Menu & Prices','المخزون والجرد':'Inventory','العملاء':'Customers','التقارير':'Reports','التقييمات':'Reviews','الإعدادات الذكية':'Settings','التنبيهات':'Alerts','تحديث':'Refresh','خروج':'Logout','الرئيسية':'Dashboard'}:{'Dashboard':'لوحة التحكم','Orders':'الطلبات','Menu & Prices':'الأصناف والأسعار','Inventory':'المخزون والجرد','Customers':'العملاء','Reports':'التقارير','Reviews':'التقييمات','Settings':'الإعدادات الذكية','Alerts':'التنبيهات','Refresh':'تحديث','Logout':'خروج'};document.querySelectorAll('button,h1,h2,h3,p,small,label').forEach(e=>{const t=e.textContent.trim();if(map[t])e.textContent=map[t]});document.querySelector('button[onclick="toggleAdminLang()"]')?.replaceChildren(document.createTextNode(adminLang==='en'?'🌐 AR':'🌐 EN'));loadOrders(true);if(document.querySelector('#page-inventory.active'))loadInventory()}
async function loadAudit(){if(window.sgRole!=='owner')return;try{const r=await fetch('api.php?action=audit_logs',{credentials:'include',cache:'no-store'});const d=await r.json();if(!d.ok){toast(d.error||'تعذر تحميل السجل');return;}document.getElementById('auditRows').innerHTML=d.logs.map(x=>`<tr><td>${esc(x.created_at||'')}</td><td><b>${esc(x.action||'')}</b></td><td>${x.order_id?('#'+x.order_id):'-'}</td><td>${esc(x.details||'')}</td></tr>`).join('')||'<tr><td colspan="4">لا توجد عمليات مسجلة</td></tr>';}catch(e){toast('تعذر الاتصال بالسيرفر')}}
async function loadSettings(){const r=await fetch('api.php?action=get_settings&key='+encodeURIComponent(key));const d=await r.json();if(!d.ok)return;settings=d.settings;const sn=document.getElementById('alertSoundName');if(sn)sn.textContent='النغمة الحالية: '+('order-chime.mp3');const ids={setWhatsapp:'whatsapp',setDriverWhatsapp:'driver_whatsapp',setAlertVolume:'alert_volume',setDiscount:'discount',setBranch:'branch',setRefresh:'auto_refresh',setOpen:'open_time',setClose:'close_time',setInsta:'instapay',setWalletNumber:'wallet_number',setAutoPrint:'auto_print',setInstagram:'instagram',setFacebook:'facebook',payCash:'payment_cash',payVisa:'payment_visa',payInsta:'payment_instapay',payWallet:'payment_wallet'};Object.entries(ids).forEach(([id,k])=>{const e=document.getElementById(id);if(e)e.value=settings[k]??''});const ocBox=document.getElementById('ownerCredsBox');if(ocBox){ocBox.style.display=window.sgRole==='owner'?'block':'none';const ocu=document.getElementById('ocUsername');if(ocu)ocu.value=settings.owner_username||'owner';}}
async function saveOwnerCreds(){const cur=document.getElementById('ocCurrent').value;const nu=document.getElementById('ocUsername').value.trim();const np=document.getElementById('ocPassword').value;if(!cur){toast('أدخل كلمة المرور الحالية');return;}const r=await fetch('api.php?action=set_owner_credentials',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({current_password:cur,new_username:nu,new_password:np})});const d=await r.json();if(d.ok){toast('تم تحديث بيانات دخول المالك بنجاح');document.getElementById('ocCurrent').value='';document.getElementById('ocPassword').value='';}else toast(d.error||'تعذر التحديث')}

function testAlertSound(){try{const a=new Audio('order-chime.mp3');a.volume=Math.max(.05,Math.min(1,Number(settings.alert_volume||.16)));a.play().catch(()=>toast('اضغط مرة أخرى للسماح بتشغيل الصوت'));}catch(e){toast('تعذر تشغيل الصوت')}}
async function saveSettings(){const b={whatsapp:v('setWhatsapp'),driver_whatsapp:v('setDriverWhatsapp'),alert_volume:v('setAlertVolume'),discount:v('setDiscount'),branch:v('setBranch'),auto_refresh:v('setRefresh'),open_time:v('setOpen'),close_time:v('setClose'),instapay:v('setInsta'),wallet_number:v('setWalletNumber'),auto_print:v('setAutoPrint'),instagram:v('setInstagram'),facebook:v('setFacebook'),payment_cash:v('payCash'),payment_visa:v('payVisa'),payment_instapay:v('payInsta'),payment_wallet:v('payWallet')};const r=await fetch('api.php?action=save_settings&key='+encodeURIComponent(key),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});const d=await r.json();if(d.ok){settings=d.settings;toast('تم حفظ الإعدادات بنجاح')}}function v(id){return document.getElementById(id)?.value||''}
async function resetData(){if(window.sgRole!=='owner'){toast('هذه العملية متاحة للـOwner فقط');return;} if(!confirm('سيتم تصفير الطلبات والتقييمات من جميع الفروع نهائيًا. هل أنت متأكد؟'))return;const r=await fetch('api.php?action=reset_data&key='+encodeURIComponent(key),{method:'POST'});const d=await r.json();if(d.ok){orders=[];renderDashboard();renderOrders();toast('تم تصفير البيانات')}}
async function loadReviewsAdmin(){const r=await fetch('api.php?action=list_reviews&key='+encodeURIComponent(key));const d=await r.json();if(!d.ok)return;document.getElementById('adminReviews').innerHTML=d.reviews.map(x=>`<div class="card"><h3>${esc(x.name)} — ★ ${x.rating}/5</h3><div class="muted">خدمة: ${x.service_rating}/5 • أكل: ${x.food_rating}/5 • ${x.created_at}</div><p>${esc(x.comment||'بدون تعليق')}</p><button class="btn ${x.approved?'red':'green'}" onclick="toggleReview(${x.id},${x.approved?0:1})">${x.approved?'إخفاء':'إظهار'}</button> <button class="btn red" onclick="deleteReview(${x.id})">حذف</button></div>`).join('')||'<div style="padding:25px;color:var(--muted)">لا توجد تقييمات</div>'}
async function toggleReview(id,approved){await fetch('api.php?action=approve_review&key='+encodeURIComponent(key),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,approved})});loadReviewsAdmin()}async function deleteReview(id){if(confirm('حذف التقييم؟')){await fetch('api.php?action=delete_review&key='+encodeURIComponent(key),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});loadReviewsAdmin()}}
let INGREDIENTS_CACHE=[];
async function loadIngredients(){try{const r=await fetch('api.php?action=list_ingredients',{credentials:'include',cache:'no-store'});const d=await r.json();if(!d.ok)return;INGREDIENTS_CACHE=d.ingredients||[];document.getElementById('ingredientRows').innerHTML=INGREDIENTS_CACHE.map(i=>`<tr><td><b>${esc(i.name_ar)}</b>${i.name_en?`<div class="muted">${esc(i.name_en)}</div>`:''}</td><td>${Number(i.stock).toLocaleString('en-US',{maximumFractionDigits:2})}</td><td>${esc(i.unit)}</td><td>${Number(i.reorder_level).toLocaleString('en-US',{maximumFractionDigits:2})}</td><td>${money(i.cost_per_unit)}</td><td>${Number(i.low)?'🔴 منخفض':'🟢 جيد'}</td><td class="actions"><button class="mini" onclick="openRestockModal(${i.id})">➕/➖ حركة</button><button class="mini" onclick="openIngredientModal(${i.id})">✏️</button><button class="mini" onclick="deleteIngredientRow(${i.id})">🗑</button></td></tr>`).join('')||'<tr><td colspan="7">لا توجد مكونات بعد</td></tr>'}catch(e){console.warn('loadIngredients failed',e)}}
function openIngredientModal(id){const i=id?INGREDIENTS_CACHE.find(x=>x.id===id):null;document.getElementById('ingId').value=i?i.id:'';document.getElementById('ingNameAr').value=i?i.name_ar:'';document.getElementById('ingNameEn').value=i?i.name_en:'';document.getElementById('ingUnit').value=i?i.unit:'g';document.getElementById('ingReorder').value=i?i.reorder_level:0;document.getElementById('ingCost').value=i?i.cost_per_unit:0;document.getElementById('ingredientModalTitle').textContent=i?'تعديل: '+i.name_ar:'مكوّن جديد';document.getElementById('ingredientModal').classList.add('open')}
function closeIngredientModal(){document.getElementById('ingredientModal').classList.remove('open')}
async function saveIngredientModal(){const b={id:Number(document.getElementById('ingId').value||0),name_ar:document.getElementById('ingNameAr').value.trim(),name_en:document.getElementById('ingNameEn').value.trim(),unit:document.getElementById('ingUnit').value,reorder_level:Number(document.getElementById('ingReorder').value||0),cost_per_unit:Number(document.getElementById('ingCost').value||0)};if(!b.name_ar){toast('اكتب اسم المكوّن');return}const r=await fetch('api.php?action=save_ingredient',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});const d=await r.json();if(d.ok){toast('تم الحفظ');closeIngredientModal();loadIngredients()}else toast(d.error||'خطأ')}
async function deleteIngredientRow(id){if(!confirm('حذف هذا المكوّن؟ سيتم حذفه من أي وصفات مرتبطة به.'))return;const r=await fetch('api.php?action=delete_ingredient',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});const d=await r.json();if(d.ok){toast('تم الحذف');loadIngredients()}}
function openRestockModal(id){document.getElementById('rsIngId').value=id;document.getElementById('rsQty').value='';document.getElementById('rsReason').value='';document.getElementById('restockModal').classList.add('open')}
function closeRestockModal(){document.getElementById('restockModal').classList.remove('open')}
async function saveRestockModal(){const id=Number(document.getElementById('rsIngId').value);const qty=Number(document.getElementById('rsQty').value||0);if(!qty){toast('أدخل كمية غير صفرية');return}const reason=document.getElementById('rsReason').value.trim();const r=await fetch('api.php?action=restock_ingredient',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,qty,reason})});const d=await r.json();if(d.ok){toast('تم تسجيل الحركة');closeRestockModal();loadIngredients();loadIngredientMovements()}else toast(d.error||'خطأ')}
async function loadIngredientMovements(){const r=await fetch('api.php?action=ingredient_movements',{credentials:'include',cache:'no-store'});const d=await r.json();if(!d.ok)return;document.getElementById('movementRows').innerHTML=(d.movements||[]).map(m=>`<tr><td>${esc(m.name_ar)}</td><td style="color:${Number(m.delta)>=0?'#3ddc84':'#ff8a8a'}">${Number(m.delta)>=0?'+':''}${Number(m.delta).toLocaleString('en-US',{maximumFractionDigits:2})}</td><td>${esc(m.reason)}</td><td>${esc(m.actor||'-')}</td><td>${esc(m.created_at)}</td></tr>`).join('')||'<tr><td colspan="5">لا توجد حركات بعد</td></tr>'}
async function loadOwnerBranchesFull(){ if(window.sgRole!=='owner')return; const r=await fetch('api.php?action=list_branches',{credentials:'include',cache:'no-store'}); const d=await r.json(); if(!d.ok)return; BRANCHES_CACHE=d.branches||[]; document.getElementById('branchMgmtRows').innerHTML=BRANCHES_CACHE.map(b=>`<tr><td><b>${esc(b.name)}</b></td><td>${Number(b.active)?'🟢 مفتوح':'🔴 مغلق'}</td><td>${esc(b.open_time||'-')} - ${esc(b.close_time||'-')}</td><td>${(b.lat&&b.lng)?'📍 محدد':'—'}</td><td class="actions"><button class="mini" onclick="toggleBranchActive('${esc(b.id)}')">${Number(b.active)?'🔴 إغلاق':'🟢 فتح'}</button><button class="mini" onclick="openBranchModal('${esc(b.id)}')">✏️ تعديل</button><button class="mini" onclick="openBranchMenuModal('${esc(b.id)}')">🍽️ المنيو</button></td></tr>`).join(''); const sel=document.getElementById('stBranch'); if(sel)sel.innerHTML=BRANCHES_CACHE.map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join(''); }
async function toggleBranchActive(id){ const r=await fetch('api.php?action=toggle_branch_active',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({branch_id:id})}); const d=await r.json(); if(d.ok){toast('تم تحديث حالة الفرع');loadOwnerBranchesFull();loadOwner();} else toast(d.error||'خطأ') }
function openBranchModal(id){ const b=BRANCHES_CACHE.find(x=>x.id===id); if(!b)return; document.getElementById('bmBranchId').value=id; document.getElementById('bmLat').value=b.lat??''; document.getElementById('bmLng').value=b.lng??''; document.getElementById('bmOpen').value=b.open_time||''; document.getElementById('bmClose').value=b.close_time||''; document.getElementById('bmPassword').value=''; document.getElementById('branchModalTitle').textContent='تعديل: '+b.name; document.getElementById('branchModal').classList.add('open') }
function closeBranchModal(){ document.getElementById('branchModal').classList.remove('open') }
async function saveBranchModal(){ const id=document.getElementById('bmBranchId').value; const body={branch_id:id,lat:document.getElementById('bmLat').value,lng:document.getElementById('bmLng').value,open_time:document.getElementById('bmOpen').value,close_time:document.getElementById('bmClose').value}; const r=await fetch('api.php?action=save_branch_details',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}); const d=await r.json(); if(!d.ok){toast(d.error||'خطأ');return} const pw=document.getElementById('bmPassword').value.trim(); if(pw){ const r2=await fetch('api.php?action=set_branch_password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({branch_id:id,password:pw})}); const d2=await r2.json(); if(!d2.ok){toast(d2.error||'خطأ في كلمة المرور');return} } toast('تم حفظ بيانات الفرع'); closeBranchModal(); loadOwnerBranchesFull() }
let BRANCH_MENU_TARGET='';
async function openBranchMenuModal(id){ BRANCH_MENU_TARGET=id; const r=await fetch('api.php?action=get_branch_menu&branch_id='+encodeURIComponent(id)); const d=await r.json(); if(!d.ok){toast(d.error||'خطأ');return} const items=(d.menu.items||[]); document.getElementById('branchMenuItems').innerHTML=items.map(it=>`<div class="product"><div class="phead"><b>${esc(it.ar)}</b><label style="font-size:11px;display:flex;align-items:center;gap:4px"><input type="checkbox" data-avail="${esc(it.id)}" ${it.branch_available?'checked':''} onchange="saveBranchOverrideRow('${esc(it.id)}')"> متاح</label></div><div class="price">السعر الأساسي: ${it.price}</div><input type="number" data-price="${esc(it.id)}" placeholder="سعر خاص بالفرع (اختياري)" value="${it.branch_price??''}" onchange="saveBranchOverrideRow('${esc(it.id)}')"></div>`).join(''); document.getElementById('branchMenuModal').classList.add('open') }
function closeBranchMenuModal(){ document.getElementById('branchMenuModal').classList.remove('open') }
async function saveBranchOverrideRow(itemId){ const box=document.querySelector(`[data-avail="${itemId}"]`); const priceInput=document.querySelector(`[data-price="${itemId}"]`); const available=box?box.checked:true; const priceVal=priceInput?priceInput.value:''; const body={branch_id:BRANCH_MENU_TARGET,item_id:itemId,available:available?1:0,use_master:(priceVal===''||priceVal===null),price:priceVal||0}; const r=await fetch('api.php?action=save_branch_override',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}); const d=await r.json(); if(d.ok)toast('تم الحفظ'); else toast(d.error||'خطأ') }
async function resetBranchMenuOverrides(){ if(!confirm('إعادة كل أصناف هذا الفرع للسعر والتوافر الأساسي؟'))return; const r=await fetch('api.php?action=reset_branch_menu&branch_id='+encodeURIComponent(BRANCH_MENU_TARGET),{method:'POST'}); const d=await r.json(); if(d.ok){toast('تم التصفير');openBranchMenuModal(BRANCH_MENU_TARGET)} }
async function loadStaffList(){ if(window.sgRole!=='owner')return; const r=await fetch('api.php?action=list_staff',{credentials:'include',cache:'no-store'}); const d=await r.json(); if(!d.ok)return; const branchName=id=>{const b=BRANCHES_CACHE.find(x=>x.id===id);return b?b.name:(id||'-')}; const roleLabel={manager:'مدير فرع',cashier:'كاشير',kitchen:'مطبخ',delivery:'دليفري'}; window.STAFF_CACHE=d.staff||[]; document.getElementById('staffRows').innerHTML=(d.staff||[]).map(s=>`<tr><td>${esc(s.username)}</td><td>${esc(s.display_name||'-')}</td><td>${roleLabel[s.role]||esc(s.role)}</td><td>${esc(branchName(s.branch_id))}</td><td>${Number(s.active)?'🟢 مفعل':'🔴 موقوف'}</td><td class="actions"><button class="mini" onclick="openStaffModal(${s.id})">✏️</button><button class="mini" onclick="toggleStaffActive(${s.id})">${Number(s.active)?'إيقاف':'تفعيل'}</button></td></tr>`).join('') }
function openStaffModal(id){ const s=id?(window.STAFF_CACHE||[]).find(x=>x.id===id):null; document.getElementById('stId').value=s?s.id:''; document.getElementById('stUsername').value=s?s.username:''; document.getElementById('stPassword').value=''; document.getElementById('stDisplay').value=s?(s.display_name||''):''; if(!document.getElementById('stBranch').options.length && BRANCHES_CACHE.length){document.getElementById('stBranch').innerHTML=BRANCHES_CACHE.map(b=>`<option value="${esc(b.id)}">${esc(b.name)}</option>`).join('')} document.getElementById('stRole').value=s?s.role:'cashier'; document.getElementById('stActive').value=s?String(s.active):'1'; if(s)document.getElementById('stBranch').value=s.branch_id; document.getElementById('staffModalTitle').textContent=s?'تعديل حساب':'حساب جديد'; document.getElementById('staffModal').classList.add('open') }
function closeStaffModal(){ document.getElementById('staffModal').classList.remove('open') }
async function saveStaffModal(){ const id=document.getElementById('stId').value; const body={id:id?Number(id):0,username:document.getElementById('stUsername').value.trim(),password:document.getElementById('stPassword').value,display_name:document.getElementById('stDisplay').value.trim(),role:document.getElementById('stRole').value,branch_id:document.getElementById('stBranch').value,active:document.getElementById('stActive').value==='1'?1:0}; const r=await fetch('api.php?action=save_staff',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}); const d=await r.json(); if(d.ok){toast('تم الحفظ');closeStaffModal();loadStaffList()} else toast(d.error||'خطأ') }
async function toggleStaffActive(id){ const r=await fetch('api.php?action=toggle_staff',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})}); const d=await r.json(); if(d.ok){toast('تم التحديث');loadStaffList()} }
async function start(){document.documentElement.lang=adminLang;document.documentElement.dir=adminLang==='en'?'ltr':'rtl';
try{const m=await fetch('api.php?action=get_menu&key='+encodeURIComponent(key)+'&_='+Date.now(),{cache:'no-store'});const md=await m.json();if(md.ok){menu=md.menu}}catch(e){console.warn('menu load failed',e)}
try{await loadSettings();}catch(e){console.warn('settings load failed',e)}
try{await loadIngredients();}catch(e){console.warn('ingredients load failed',e)}
try{await loadOrders();}catch(e){console.warn('orders load failed',e)}
setDates();startLiveSync();document.querySelector('[data-page=dashboard]').classList.add('active');
window.addEventListener('pointerdown',()=>{try{if(typeof unlockAlarmAudio==='function')unlockAlarmAudio(true);}catch(e){}},{once:true,passive:true});
window.addEventListener('keydown',()=>{try{if(typeof unlockAlarmAudio==='function')unlockAlarmAudio(true);}catch(e){}},{once:true,passive:true});
try{if(typeof unlockAlarmAudio==='function')unlockAlarmAudio(false);}catch(e){}}
checkAdminSession().then(ok=>{if(!ok){document.getElementById('loginKey').focus();}})
</script><script src="https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js" defer></script></body></html>
